#!/usr/bin/env python3
"""Run a sequence of commands in the original (or mine with MINE=1) and print each reply/error.
usage: pr.py [-f file] 'cmd {json}' ['cmd {json}' ...]
Each arg is one command; a reply is printed compactly; stops at the first error (as `run` does)."""
import json, os, subprocess, sys, tempfile, shutil

EXE = os.environ.get('EXE', '/workspace/executable')
if os.environ.get('MINE'):
    EXE = '/workspace/.claude/worktrees/agent-a31569566c799be2a/target/release/bimcraft-cli'


def run(cmds, files=(), keep=None):
    d = tempfile.mkdtemp(prefix='pr', dir='/tmp/family-agent')
    for f in files:
        shutil.copy(f, d)
    args = [EXE, 'run'] + [os.path.basename(f) for f in files if f.endswith('.bimcraft')][:1]
    for c in cmds:
        args += ['--cmd', c]
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=120)
    out = p.stdout.decode('utf-8', 'replace')
    err = p.stderr.decode('utf-8', 'replace')
    if keep:
        for f in os.listdir(d):
            shutil.copy(os.path.join(d, f), keep)
    shutil.rmtree(d)
    return p.returncode, out, err


if __name__ == '__main__':
    a = sys.argv[1:]
    files = []
    keep = None
    while a and a[0] in ('-f', '-k'):
        if a[0] == '-f':
            files.append(a[1])
        else:
            keep = a[1]
        a = a[2:]
    code, out, err = run(a, files, keep)
    trunc = int(os.environ.get('TRUNC', '3000'))
    for line in out.splitlines():
        print(line[:trunc] + ('...' if len(line) > trunc else ''))
    if err:
        print('ERR:', err.rstrip()[:trunc * 3])
    print('[exit %d]' % code)

