#!/usr/bin/env python3
"""Find the order in which the family command checks its keys: each key gets a bad value; for
every pair, which one's error wins."""
import json, subprocess, sys, tempfile, os, itertools, functools

EXE = '/workspace/executable'
BAD = {
    'category': '"bad"',
    'parameters': '5',
    'types': '5',
    'forms': '5',
    'symbols': '5',
    'connectors': '5',
    'operation': '5',
    'kind': '5',
    'rename': '5',
    'delete': '5',
    'dry_run': '5',
    'path': '5',
    'save': '5',
    'form': '5',
    'symbol': '5',
    'delete_form': '5',
    'delete_symbol': '5',
}
if len(sys.argv) > 1:
    BAD = json.loads(open(sys.argv[1]).read())


def run(body):
    d = tempfile.mkdtemp(prefix='ord', dir='/tmp/family-agent')
    p = subprocess.run([EXE, 'run', '--cmd', 'family {"name":"Table",' + body + '}'], cwd=d, capture_output=True)
    subprocess.run(['rm', '-rf', d])
    return p.stderr.decode().strip()


single = {}
for k, v in BAD.items():
    single[k] = run(f'"{k}":{v}')
    print(k, '->', single[k][:150])

wins = {}
for a, b in itertools.combinations(BAD, 2):
    e = run(f'"{a}":{BAD[a]},"{b}":{BAD[b]}')
    if e == single[a]:
        wins[(a, b)] = a
    elif e == single[b]:
        wins[(a, b)] = b
    else:
        wins[(a, b)] = '?' + e[:100]

order = sorted(BAD, key=lambda k: -sum(1 for (x, y), w in wins.items() if w == k))
print('order (most wins first):', order)
for (a, b), w in wins.items():
    if w.startswith('?'):
        print('odd', a, b, w)

