fn indent(out: &mut String, n: usize) {
    for _ in 0..n {
        out.push_str("  ");
    }
}

pub fn write_pretty(v: &Value, out: &mut String, level: usize) {
    match v {
        Value::Arr(a) => {
            if a.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push('[');
            for (i, x) in a.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('\n');
                indent(out, level + 1);
                write_pretty(x, out, level + 1);
            }
            out.push('\n');
            indent(out, level);
            out.push(']');
        }
        Value::Obj(m) => {
            if m.items.is_empty() {
                out.push_str("{}");
                return;
            }
            out.push('{');
            for (i, (k, x)) in m.items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('\n');
                indent(out, level + 1);
                write_str(k, out);
                out.push_str(": ");
                write_pretty(x, out, level + 1);
            }
            out.push('\n');
            indent(out, level);
            out.push('}');
        }
        _ => write_compact(v, out),
    }
}

