"""Helpers to run the original (or mine) on a list of commands."""
import json, os, subprocess, tempfile, shutil

ORIG = '/workspace/executable'
MINE = '/workspace/.claude/worktrees/agent-a31569566c799be2a/target/release/bimcraft-cli'


def run(cmds, files=(), exe=ORIG, keep=None, project=None, env=None):
    """cmds: list of 'id {json}' strings or (id, dict) tuples. Returns (code, [stdout lines], stderr)."""
    d = tempfile.mkdtemp(prefix='lib', dir='/tmp/family-agent')
    for f in files:
        shutil.copy(f, d)
    args = [exe, 'run']
    if project:
        args.append(project)
    for c in cmds:
        if isinstance(c, tuple):
            c = c[0] + ' ' + json.dumps(c[1])
        args += ['--cmd', c]
    e = dict(os.environ)
    if env:
        e.update(env)
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=300, env=e)
    out = p.stdout.decode('utf-8', 'replace').splitlines()
    err = p.stderr.decode('utf-8', 'replace').strip()
    if keep:
        os.makedirs(keep, exist_ok=True)
        for f in os.listdir(d):
            src = os.path.join(d, f)
            if os.path.isfile(src):
                shutil.copy(src, keep)
    shutil.rmtree(d)
    return p.returncode, out, err


def fam(cmd_body, exe=ORIG, extra=()):
    """Run `family {body}` (+ extra commands); return the error or the last reply as a dict."""
    code, out, err = run([('family', cmd_body)] + list(extra), exe=exe)
    if code != 0:
        return 'ERR ' + err
    return json.loads(out[-1])


def short(x, n=300):
    s = x if isinstance(x, str) else json.dumps(x)
    return s if len(s) <= n else s[:n] + '...'

