//! A family as the original holds it in memory (its materials by name), read from the project
//! file's JSON (materials by GUID) and written back to it, and shown as `family` and `inspect`
//! show it.

use crate::json::{Map, Num, Value};

/// A size: a number of mm (or degrees), or a formula over the family's parameters.
#[derive(Clone, Debug, PartialEq)]
pub enum Expr {
    Num(f64),
    Text(String),
}

impl Expr {
    pub fn value(&self) -> Value {
        match self {
            Expr::Num(x) => Value::f(*x),
            Expr::Text(s) => Value::s(s),
        }
    }
    /// From a file: a number or a formula's text (anything else, none).
    pub fn from_value(v: &Value) -> Option<Expr> {
        match v {
            Value::Num(n) => Some(Expr::Num(n.as_f64())),
            Value::Str(s) => Some(Expr::Text(s.clone())),
            _ => None,
        }
    }
    pub fn zero() -> Expr {
        Expr::Num(0.0)
    }
}

/// What a part's `guid` names: a GUID, or (as a command may give it) an element's id.
#[derive(Clone, Debug, PartialEq)]
pub enum GRef {
    Guid(String),
    Id(u64),
}

impl GRef {
    pub fn value(&self) -> Value {
        match self {
            GRef::Guid(g) => Value::s(g),
            GRef::Id(n) => Value::u(*n),
        }
    }
    pub fn guid(&self) -> Option<&str> {
        match self {
            GRef::Guid(g) => Some(g),
            GRef::Id(_) => None,
        }
    }
}

/// A parameter's kind.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Length,
    Number,
    Angle,
    YesNo,
    Material,
}

pub const KINDS: &[&str] = &["length", "number", "angle", "yesno", "material"];

impl Kind {
    pub fn name(self) -> &'static str {
        match self {
            Kind::Length => "length",
            Kind::Number => "number",
            Kind::Angle => "angle",
            Kind::YesNo => "yesno",
            Kind::Material => "material",
        }
    }
    pub fn parse(s: &str) -> Option<Kind> {
        Some(match s {
            "length" => Kind::Length,
            "number" => Kind::Number,
            "angle" => Kind::Angle,
            "yesno" => Kind::YesNo,
            "material" => Kind::Material,
            _ => return None,
        })
    }
}

/// A family parameter: each type's, or with `instance` each component's. Its `value` is the
/// JSON it was given (a number as written, a yes/no, a material's name), null for none.
#[derive(Clone, Debug, PartialEq)]
pub struct Param {
    pub name: String,
    pub kind: Kind,
    pub instance: bool,
    pub value: Value,
    pub formula: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Plane {
    XY,
    XZ,
    YZ,
}

pub const PLANES: &[&str] = &["xy", "xz", "yz"];

impl Plane {
    pub fn name(self) -> &'static str {
        match self {
            Plane::XY => "xy",
            Plane::XZ => "xz",
            Plane::YZ => "yz",
        }
    }
    pub fn parse(s: &str) -> Option<Plane> {
        Some(match s {
            "xy" => Plane::XY,
            "xz" => Plane::XZ,
            "yz" => Plane::YZ,
            _ => return None,
        })
    }
}

pub type Pt = [Expr; 2];

#[derive(Clone, Debug, PartialEq)]
pub struct Circle {
    pub centre: Pt,
    pub radius: Expr,
}

/// A form: a profile (or a circle) in a sketch plane swept from `from` to `to`, or turned about
/// an `axis` from `from` to `to` degrees, or triangles as a file brings them (`mesh`).
#[derive(Clone, Debug, PartialEq)]
pub struct Form {
    pub id: Option<u64>,
    pub guid: Option<GRef>,
    pub plane: Plane,
    pub profile: Vec<Pt>,
    pub circle: Option<Circle>,
    pub from: Expr,
    pub to: Expr,
    pub axis: Option<[Pt; 2]>,
    pub void: bool,
    /// A material's name or a material parameter's; "" for none.
    pub material: String,
    pub visible: Option<Expr>,
    pub mesh: Vec<[[f64; 3]; 3]>,
}

impl Default for Form {
    fn default() -> Form {
        Form {
            id: None,
            guid: None,
            plane: Plane::XY,
            profile: Vec::new(),
            circle: None,
            from: Expr::zero(),
            to: Expr::zero(),
            axis: None,
            void: false,
            material: String::new(),
            visible: None,
            mesh: Vec::new(),
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Arc {
    pub centre: Pt,
    pub radius: Expr,
    pub from: Expr,
    pub to: Expr,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Align {
    Left,
    Center,
    Right,
}

pub const ALIGNS: &[&str] = &["left", "center", "right"];

impl Align {
    pub fn name(self) -> &'static str {
        match self {
            Align::Left => "left",
            Align::Center => "center",
            Align::Right => "right",
        }
    }
    pub fn parse(s: &str) -> Option<Align> {
        Some(match s {
            "left" => Align::Left,
            "center" => Align::Center,
            "right" => Align::Right,
            _ => return None,
        })
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Text {
    pub at: Pt,
    pub height: Expr,
    pub value: String,
    pub align: Align,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Dot {
    pub centre: Pt,
    pub radius: Expr,
}

/// A plan symbol: one of a line, an arc, a text or a dot.
#[derive(Clone, Debug, PartialEq, Default)]
pub struct Symbol {
    pub id: Option<u64>,
    pub guid: Option<GRef>,
    pub line: Vec<Pt>,
    pub arc: Option<Arc>,
    pub text: Option<Text>,
    pub dot: Option<Dot>,
    pub visible: Option<Expr>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ConnKind {
    Power,
    Switch,
}

pub const CONN_KINDS: &[&str] = &["power", "switch"];

impl ConnKind {
    pub fn name(self) -> &'static str {
        match self {
            ConnKind::Power => "power",
            ConnKind::Switch => "switch",
        }
    }
    pub fn parse(s: &str) -> Option<ConnKind> {
        Some(match s {
            "power" => ConnKind::Power,
            "switch" => ConnKind::Switch,
            _ => return None,
        })
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum System {
    Balanced,
    Unbalanced,
    Switch,
}

pub const SYSTEMS: &[&str] = &["power-balanced", "power-unbalanced", "switch"];

impl System {
    pub fn name(self) -> &'static str {
        match self {
            System::Balanced => "power-balanced",
            System::Unbalanced => "power-unbalanced",
            System::Switch => "switch",
        }
    }
    pub fn parse(s: &str) -> Option<System> {
        Some(match s {
            "power-balanced" => System::Balanced,
            "power-unbalanced" => System::Unbalanced,
            "switch" => System::Switch,
            _ => return None,
        })
    }
}

/// A connector's load: one for the device, or one for each pole.
#[derive(Clone, Debug, PartialEq)]
pub enum Load {
    One(Expr),
    PerPole(Vec<Expr>),
}

impl Load {
    pub fn value(&self) -> Value {
        match self {
            Load::One(e) => e.value(),
            Load::PerPole(v) => Value::Arr(v.iter().map(|e| e.value()).collect()),
        }
    }
}

/// What an electrical device draws (or a switch switches).
#[derive(Clone, Debug, PartialEq)]
pub struct Connector {
    pub id: Option<u64>,
    pub guid: Option<GRef>,
    pub kind: ConnKind,
    pub system: System,
    pub poles: u8,
    pub voltage: Expr,
    pub load_va: Load,
    pub power_factor: Expr,
    pub classification: String,
}

/// The categories a family may be of, in the original's order.
pub const CATEGORIES: &[&str] = &[
    "furniture",
    "casework",
    "plumbing",
    "drain",
    "pipefitting",
    "pipeaccessory",
    "equipment",
    "outlet",
    "switch",
    "airterminal",
    "earthing",
    "inspectionbox",
    "lighting",
    "generic",
    "dataoutlet",
    "voiceoutlet",
    "patchpanel",
    "rack",
    "door",
    "window",
];

/// The kinds a category's fixtures and fittings may be (none for the others).
pub fn kinds_of(category: &str) -> &'static [&'static str] {
    match category {
        "plumbing" => &["wc", "lav", "sink", "laundry", "shower", "bath", "bidet", "urinal"],
        "drain" => &["floor_drain", "floor_waste", "roof_drain"],
        "pipefitting" => &["bend", "tee", "cross", "transition", "coupling"],
        _ => &[],
    }
}

/// How a door or a window opens.
pub const OPERATIONS: &[&str] = &["swing", "double-swing", "sliding", "double-sliding", "folding", "fixed"];

/// A family.
#[derive(Clone, Debug, PartialEq)]
pub struct Family {
    pub category: String,
    pub kind: Option<String>,
    pub parameters: Vec<Param>,
    /// Its types by name (in name order), each its parameters' values by name.
    pub types: Vec<(String, Map)>,
    pub forms: Vec<Form>,
    pub symbols: Vec<Symbol>,
    pub operation: Option<String>,
    pub connectors: Vec<Connector>,
}

impl Default for Family {
    fn default() -> Family {
        Family {
            category: "furniture".into(),
            kind: None,
            parameters: Vec::new(),
            types: Vec::new(),
            forms: Vec::new(),
            symbols: Vec::new(),
            operation: None,
            connectors: Vec::new(),
        }
    }
}

impl Family {
    /// Whether it stands in a wall (a door's or a window's).
    pub fn hosted(&self) -> bool {
        self.category == "door" || self.category == "window"
    }
    pub fn param(&self, name: &str) -> Option<&Param> {
        self.parameters.iter().find(|p| p.name == name)
    }
    pub fn type_values(&self, name: &str) -> Option<&Map> {
        self.types.iter().find(|(n, _)| n == name).map(|(_, m)| m)
    }
    pub fn type_names(&self) -> Vec<String> {
        self.types.iter().map(|(n, _)| n.clone()).collect()
    }
    /// Sets a type's values, keeping the types in name order.
    pub fn set_type(&mut self, name: &str, values: Map) {
        match self.types.binary_search_by(|(n, _)| n.as_str().cmp(name)) {
            Ok(i) => self.types[i].1 = values,
            Err(i) => self.types.insert(i, (name.to_string(), values)),
        }
    }
    pub fn remove_type(&mut self, name: &str) {
        self.types.retain(|(n, _)| n != name);
    }
    /// The material parameters' names.
    pub fn material_params(&self) -> Vec<String> {
        self.parameters.iter().filter(|p| p.kind == Kind::Material).map(|p| p.name.clone()).collect()
    }
}

// ---------------------------------------------------------------- the project file's form

fn pt_from(v: &Value) -> Pt {
    let a = v.as_arr();
    let at = |i: usize| a.and_then(|a| a.get(i)).and_then(Expr::from_value).unwrap_or_else(Expr::zero);
    [at(0), at(1)]
}

fn pts_from(v: Option<&Value>) -> Vec<Pt> {
    v.and_then(|x| x.as_arr()).map(|a| a.iter().map(pt_from).collect()).unwrap_or_default()
}

fn expr_of(v: Option<&Value>, d: Expr) -> Expr {
    v.and_then(Expr::from_value).unwrap_or(d)
}

fn id_from(v: &Value) -> Option<u64> {
    v.get("id").and_then(|x| x.as_u64()).filter(|n| *n != 0)
}

fn guid_from(v: &Value) -> Option<GRef> {
    match v.get("guid") {
        Some(Value::Str(s)) if !s.is_empty() => Some(GRef::Guid(s.clone())),
        Some(Value::Num(Num::U(n))) if *n != 0 => Some(GRef::Id(*n)),
        _ => None,
    }
}

fn str_of(v: Option<&Value>) -> String {
    v.and_then(|x| x.as_str()).unwrap_or("").to_string()
}

fn form_from(v: &Value, mat: &dyn Fn(&str) -> String) -> Form {
    let circle = v.get("circle").filter(|c| !c.is_null()).map(|c| Circle {
        centre: c.get("centre").map(pt_from).unwrap_or([Expr::zero(), Expr::zero()]),
        radius: expr_of(c.get("radius"), Expr::zero()),
    });
    let axis = v.get("axis").and_then(|a| a.as_arr()).map(|a| {
        [a.first().map(pt_from).unwrap_or([Expr::zero(), Expr::zero()]), a.get(1).map(pt_from).unwrap_or([Expr::zero(), Expr::zero()])]
    });
    let mesh = v
        .get("mesh")
        .and_then(|m| m.as_arr())
        .map(|tris| {
            tris.iter()
                .map(|t| {
                    let mut out = [[0.0; 3]; 3];
                    for (i, p) in t.as_arr().map(|x| x.as_slice()).unwrap_or(&[]).iter().take(3).enumerate() {
                        for (j, c) in p.as_arr().map(|x| x.as_slice()).unwrap_or(&[]).iter().take(3).enumerate() {
                            out[i][j] = c.as_f64().unwrap_or(0.0);
                        }
                    }
                    out
                })
                .collect()
        })
        .unwrap_or_default();
    let material = str_of(v.get("material"));
    Form {
        id: id_from(v),
        guid: guid_from(v),
        plane: v.get("plane").and_then(|p| p.as_str()).and_then(Plane::parse).unwrap_or(Plane::XY),
        profile: pts_from(v.get("profile")),
        circle,
        from: expr_of(v.get("from"), Expr::zero()),
        to: expr_of(v.get("to"), Expr::zero()),
        axis,
        void: v.get("void").and_then(|x| x.as_bool()).unwrap_or(false),
        material: if material.is_empty() { material } else { mat(&material) },
        visible: v.get("visible").and_then(Expr::from_value),
        mesh,
    }
}

fn symbol_from(v: &Value) -> Symbol {
    let arc = v.get("arc").filter(|c| !c.is_null()).map(|c| Arc {
        centre: c.get("centre").map(pt_from).unwrap_or([Expr::zero(), Expr::zero()]),
        radius: expr_of(c.get("radius"), Expr::zero()),
        from: expr_of(c.get("from"), Expr::zero()),
        to: expr_of(c.get("to"), Expr::zero()),
    });
    let text = v.get("text").filter(|c| !c.is_null()).map(|c| Text {
        at: c.get("at").map(pt_from).unwrap_or([Expr::zero(), Expr::zero()]),
        height: expr_of(c.get("height"), Expr::zero()),
        value: str_of(c.get("value")),
        align: c.get("align").and_then(|a| a.as_str()).and_then(Align::parse).unwrap_or(Align::Left),
    });
    let dot = v.get("dot").filter(|c| !c.is_null()).map(|c| Dot {
        centre: c.get("centre").map(pt_from).unwrap_or([Expr::zero(), Expr::zero()]),
        radius: expr_of(c.get("radius"), Expr::zero()),
    });
    Symbol {
        id: id_from(v),
        guid: guid_from(v),
        line: pts_from(v.get("line")),
        arc,
        text,
        dot,
        visible: v.get("visible").and_then(Expr::from_value),
    }
}

fn connector_from(v: &Value) -> Connector {
    let load_va = match v.get("load_va") {
        Some(Value::Arr(a)) => Load::PerPole(a.iter().map(|x| Expr::from_value(x).unwrap_or_else(Expr::zero)).collect()),
        Some(x) => Load::One(Expr::from_value(x).unwrap_or_else(Expr::zero)),
        None => Load::One(Expr::zero()),
    };
    Connector {
        id: id_from(v),
        guid: guid_from(v),
        kind: v.get("kind").and_then(|k| k.as_str()).and_then(ConnKind::parse).unwrap_or(ConnKind::Power),
        system: v.get("system").and_then(|k| k.as_str()).and_then(System::parse).unwrap_or(System::Balanced),
        poles: v.get("poles").and_then(|x| x.as_u64()).map(|n| n.min(255) as u8).unwrap_or(1),
        voltage: expr_of(v.get("voltage"), Expr::zero()),
        load_va,
        power_factor: expr_of(v.get("power_factor"), Expr::Num(1.0)),
        classification: str_of(v.get("classification")),
    }
}

/// A family as the project file holds it, read: `mat` turns a material's GUID into its name
/// (anything else stays as it is).
pub fn from_file(v: &Value, mat: &dyn Fn(&str) -> String) -> Family {
    let parameters: Vec<Param> = v
        .get("parameters")
        .and_then(|p| p.as_arr())
        .map(|a| {
            a.iter()
                .map(|p| {
                    let kind = p.get("kind").and_then(|k| k.as_str()).and_then(Kind::parse).unwrap_or(Kind::Length);
                    let mut value = p.get("value").cloned().unwrap_or(Value::Null);
                    if kind == Kind::Material {
                        if let Value::Str(s) = &value {
                            if !s.is_empty() {
                                value = Value::Str(mat(s));
                            }
                        }
                    }
                    Param {
                        name: str_of(p.get("name")),
                        kind,
                        instance: p.get("instance").and_then(|x| x.as_bool()).unwrap_or(false),
                        value,
                        formula: p.get("formula").and_then(|f| f.as_str()).map(|s| s.to_string()),
                    }
                })
                .collect()
        })
        .unwrap_or_default();
    let mats: Vec<String> = parameters.iter().filter(|p| p.kind == Kind::Material).map(|p| p.name.clone()).collect();
    let mut types: Vec<(String, Map)> = Vec::new();
    if let Some(Value::Obj(ts)) = v.get("types") {
        for (n, t) in ts.iter() {
            let mut m = Map::new();
            if let Value::Obj(vals) = t {
                for (k, x) in vals.iter() {
                    let x = match x {
                        Value::Str(s) if mats.contains(k) && !s.is_empty() => Value::Str(mat(s)),
                        _ => x.clone(),
                    };
                    m.insert_sorted(k, x);
                }
            }
            types.push((n.clone(), m));
        }
        types.sort_by(|a, b| a.0.cmp(&b.0));
        types.dedup_by(|a, b| a.0 == b.0);
    }
    let forms = v
        .get("forms")
        .and_then(|f| f.as_arr())
        .map(|a| {
            a.iter()
                .map(|f| {
                    let mut fo = form_from(f, mat);
                    // a material parameter's name is the parameter's, whatever a material is named
                    if !fo.material.is_empty() {
                        let raw = str_of(f.get("material"));
                        if mats.contains(&raw) {
                            fo.material = raw;
                        }
                    }
                    fo
                })
                .collect()
        })
        .unwrap_or_default();
    Family {
        category: v.get("category").and_then(|c| c.as_str()).unwrap_or("furniture").to_string(),
        kind: v.get("kind").and_then(|k| k.as_str()).map(|s| s.to_string()),
        parameters,
        types,
        forms,
        symbols: v.get("symbols").and_then(|s| s.as_arr()).map(|a| a.iter().map(symbol_from).collect()).unwrap_or_default(),
        operation: v.get("operation").and_then(|o| o.as_str()).map(|s| s.to_string()),
        connectors: v.get("connectors").and_then(|s| s.as_arr()).map(|a| a.iter().map(connector_from).collect()).unwrap_or_default(),
    }
}

fn pt_value(p: &Pt) -> Value {
    Value::Arr(vec![p[0].value(), p[1].value()])
}

fn pts_value(v: &[Pt]) -> Value {
    Value::Arr(v.iter().map(pt_value).collect())
}

fn form_value(f: &Form, material: &str) -> Value {
    let mut m = Map::new();
    if let Some(id) = f.id {
        m.insert("id", Value::u(id));
    }
    if let Some(g) = &f.guid {
        m.insert("guid", g.value());
    }
    m.insert("plane", Value::s(f.plane.name()));
    if !f.profile.is_empty() {
        m.insert("profile", pts_value(&f.profile));
    }
    if let Some(c) = &f.circle {
        m.insert("circle", crate::jobj! {"centre" => pt_value(&c.centre), "radius" => c.radius.value()});
    }
    m.insert("from", f.from.value());
    m.insert("to", f.to.value());
    if let Some(a) = &f.axis {
        m.insert("axis", Value::Arr(vec![pt_value(&a[0]), pt_value(&a[1])]));
    }
    if f.void {
        m.insert("void", Value::Bool(true));
    }
    if !material.is_empty() {
        m.insert("material", Value::s(material));
    }
    if let Some(v) = &f.visible {
        m.insert("visible", v.value());
    }
    if !f.mesh.is_empty() {
        let tris: Vec<Value> = f
            .mesh
            .iter()
            .map(|t| Value::Arr(t.iter().map(|p| Value::Arr(p.iter().map(|c| Value::f(*c)).collect())).collect()))
            .collect();
        m.insert("mesh", Value::Arr(tris));
    }
    Value::Obj(m)
}

pub fn symbol_value(s: &Symbol) -> Value {
    let mut m = Map::new();
    if let Some(id) = s.id {
        m.insert("id", Value::u(id));
    }
    if let Some(g) = &s.guid {
        m.insert("guid", g.value());
    }
    if !s.line.is_empty() {
        m.insert("line", pts_value(&s.line));
    }
    if let Some(a) = &s.arc {
        m.insert(
            "arc",
            crate::jobj! {"centre" => pt_value(&a.centre), "radius" => a.radius.value(), "from" => a.from.value(), "to" => a.to.value()},
        );
    }
    if let Some(t) = &s.text {
        let mut tm = Map::new();
        tm.insert("at", pt_value(&t.at));
        tm.insert("height", t.height.value());
        tm.insert("value", Value::s(&t.value));
        if t.align != Align::Left {
            tm.insert("align", Value::s(t.align.name()));
        }
        m.insert("text", Value::Obj(tm));
    }
    if let Some(d) = &s.dot {
        m.insert("dot", crate::jobj! {"centre" => pt_value(&d.centre), "radius" => d.radius.value()});
    }
    if let Some(v) = &s.visible {
        m.insert("visible", v.value());
    }
    Value::Obj(m)
}

pub fn connector_value(c: &Connector) -> Value {
    let mut m = Map::new();
    if let Some(id) = c.id {
        m.insert("id", Value::u(id));
    }
    if let Some(g) = &c.guid {
        m.insert("guid", g.value());
    }
    m.insert("kind", Value::s(c.kind.name()));
    m.insert("system", Value::s(c.system.name()));
    m.insert("poles", Value::u(c.poles as u64));
    m.insert("voltage", c.voltage.value());
    m.insert("load_va", c.load_va.value());
    m.insert("power_factor", c.power_factor.value());
    if !c.classification.is_empty() {
        m.insert("classification", Value::s(&c.classification));
    }
    Value::Obj(m)
}

fn param_value(p: &Param, value: Value) -> Value {
    let mut m = Map::new();
    m.insert("name", Value::s(&p.name));
    m.insert("kind", Value::s(p.kind.name()));
    if p.instance {
        m.insert("instance", Value::Bool(true));
    }
    m.insert("value", value);
    if let Some(f) = &p.formula {
        m.insert("formula", Value::s(f));
    }
    Value::Obj(m)
}

impl Family {
    /// As the file holds it (the original's field order), `mat` giving a material's GUID by
    /// name (None leaves the name).
    pub fn to_file(&self, mat: &dyn Fn(&str) -> Option<String>) -> Value {
        self.write(&|s: &str| mat(s).unwrap_or_else(|| s.to_string()))
    }

    /// As `family` and `inspect` show it: materials by name.
    pub fn view(&self) -> Value {
        self.write(&|s: &str| s.to_string())
    }

    fn write(&self, mat: &dyn Fn(&str) -> String) -> Value {
        let mats = self.material_params();
        let mut m = Map::new();
        m.insert("category", Value::s(&self.category));
        if let Some(k) = &self.kind {
            m.insert("kind", Value::s(k));
        }
        let params: Vec<Value> = self
            .parameters
            .iter()
            .map(|p| {
                let v = match (&p.value, p.kind) {
                    (Value::Str(s), Kind::Material) if !s.is_empty() => Value::Str(mat(s)),
                    (v, _) => v.clone(),
                };
                param_value(p, v)
            })
            .collect();
        m.insert("parameters", Value::Arr(params));
        let mut types = Map::new();
        for (n, vals) in &self.types {
            let mut t = Map::new();
            for (k, x) in vals.iter() {
                let x = match x {
                    Value::Str(s) if mats.contains(k) && !s.is_empty() => Value::Str(mat(s)),
                    _ => x.clone(),
                };
                t.insert_sorted(k, x);
            }
            types.insert_sorted(n, Value::Obj(t));
        }
        m.insert("types", Value::Obj(types));
        let forms: Vec<Value> = self
            .forms
            .iter()
            .map(|f| {
                let material = if f.material.is_empty() || mats.contains(&f.material) {
                    f.material.clone()
                } else {
                    mat(&f.material)
                };
                form_value(f, &material)
            })
            .collect();
        m.insert("forms", Value::Arr(forms));
        if !self.symbols.is_empty() {
            m.insert("symbols", Value::Arr(self.symbols.iter().map(symbol_value).collect()));
        }
        if let Some(o) = &self.operation {
            m.insert("operation", Value::s(o));
        }
        if !self.connectors.is_empty() {
            m.insert("connectors", Value::Arr(self.connectors.iter().map(connector_value).collect()));
        }
        Value::Obj(m)
    }
}

//! Reading a `family` command's parts as the original's serde reads them from a JSON value:
//! objects key by key in name order (as serde_json's map holds them), unknown keys refused, a
//! missing one said after the others, and sequences field by field; with serde's very words.

use super::model::*;
use crate::json::{fmt_f64, Map, Num, Value};

pub type DeR<T> = Result<T, String>;

/// A value as serde names it in "invalid type" errors.
pub fn unexpected(v: &Value) -> String {
    match v {
        Value::Null => "null".into(),
        Value::Bool(b) => format!("boolean `{}`", b),
        Value::Num(Num::U(u)) => format!("integer `{}`", u),
        Value::Num(Num::I(i)) => format!("integer `{}`", i),
        Value::Num(Num::F(f)) => format!("floating point `{}`", fmt_f64(*f)),
        Value::Str(s) => format!("string {:?}", s),
        Value::Arr(_) => "sequence".into(),
        Value::Obj(_) => "map".into(),
    }
}

pub fn invalid(v: &Value, what: &str) -> String {
    format!("invalid type: {}, expected {}", unexpected(v), what)
}

/// serde's "expected" list of names: `a`; `a` or `b`; one of `a`, `b`, `c`.
pub fn one_of(names: &[&str]) -> String {
    match names.len() {
        0 => "there are no variants".into(),
        1 => format!("`{}`", names[0]),
        2 => format!("`{}` or `{}`", names[0], names[1]),
        _ => format!("one of {}", names.iter().map(|n| format!("`{}`", n)).collect::<Vec<_>>().join(", ")),
    }
}

pub fn de_string(v: &Value) -> DeR<String> {
    match v {
        Value::Str(s) => Ok(s.clone()),
        _ => Err(invalid(v, "a string")),
    }
}

pub fn de_bool(v: &Value) -> DeR<bool> {
    match v {
        Value::Bool(b) => Ok(*b),
        _ => Err(invalid(v, "a boolean")),
    }
}

pub fn de_u64(v: &Value) -> DeR<u64> {
    match v {
        Value::Num(Num::U(u)) => Ok(*u),
        Value::Num(Num::I(i)) => Err(format!("invalid value: integer `{}`, expected u64", i)),
        _ => Err(invalid(v, "u64")),
    }
}

pub fn de_u8(v: &Value) -> DeR<u8> {
    match v {
        Value::Num(Num::U(u)) if *u <= 255 => Ok(*u as u8),
        Value::Num(Num::U(u)) => Err(format!("invalid value: integer `{}`, expected u8", u)),
        Value::Num(Num::I(i)) => Err(format!("invalid value: integer `{}`, expected u8", i)),
        _ => Err(invalid(v, "u8")),
    }
}

pub fn de_f64(v: &Value) -> DeR<f64> {
    match v {
        Value::Num(n) => Ok(n.as_f64()),
        _ => Err(invalid(v, "f64")),
    }
}

pub fn de_expr(v: &Value) -> DeR<Expr> {
    match v {
        Value::Num(n) => Ok(Expr::Num(n.as_f64())),
        Value::Str(s) => Ok(Expr::Text(s.clone())),
        _ => Err("data did not match any variant of untagged enum Expr".into()),
    }
}

fn de_opt<T>(v: &Value, f: impl Fn(&Value) -> DeR<T>) -> DeR<Option<T>> {
    match v {
        Value::Null => Ok(None),
        _ => f(v).map(Some),
    }
}

/// A unit enum's variant: by name, or as a map of one key.
pub fn de_variant(v: &Value, variants: &[&str]) -> DeR<String> {
    let unknown = |s: &str| format!("unknown variant `{}`, expected {}", s, one_of(variants));
    match v {
        Value::Str(s) => {
            if variants.contains(&s.as_str()) {
                Ok(s.clone())
            } else {
                Err(unknown(s))
            }
        }
        Value::Obj(m) => {
            if m.len() != 1 {
                return Err("invalid value: map, expected map with a single key".into());
            }
            let (k, x) = &m.items[0];
            if !variants.contains(&k.as_str()) {
                return Err(unknown(k));
            }
            match x {
                Value::Null => Ok(k.clone()),
                other => Err(invalid(other, "unit")),
            }
        }
        _ => Err(invalid(v, "string or map")),
    }
}

/// A fixed-size array of `n` elements, each read by `f`.
fn de_array<T>(v: &Value, n: usize, f: &dyn Fn(&Value) -> DeR<T>) -> DeR<Vec<T>> {
    let what = format!("an array of length {}", n);
    match v {
        Value::Arr(a) => {
            let mut out = Vec::with_capacity(n);
            for i in 0..n {
                match a.get(i) {
                    Some(x) => out.push(f(x)?),
                    None => return Err(format!("invalid length {}, expected {}", i, what)),
                }
            }
            if a.len() > n {
                return Err(format!("invalid length {}, expected fewer elements in array", a.len()));
            }
            Ok(out)
        }
        _ => Err(invalid(v, &what)),
    }
}

pub fn de_seq<T>(v: &Value, f: &dyn Fn(&Value) -> DeR<T>) -> DeR<Vec<T>> {
    match v {
        Value::Arr(a) => a.iter().map(f).collect(),
        _ => Err(invalid(v, "a sequence")),
    }
}

pub fn de_point(v: &Value) -> DeR<Pt> {
    let a = de_array(v, 2, &de_expr)?;
    let mut it = a.into_iter();
    Ok([it.next().unwrap(), it.next().unwrap()])
}

fn de_points(v: &Value) -> DeR<Vec<Pt>> {
    de_seq(v, &de_point)
}

/// A part's `guid`: a GUID (not one of the ids the original writes as GUIDs), or an element's
/// id (a whole number, or one in a string); 0 is none.
pub fn de_gref(v: &Value) -> DeR<GRef> {
    match v {
        Value::Str(s) => {
            if let Some(g) = real_guid(s) {
                return Ok(GRef::Guid(g));
            }
            let t = s.trim();
            if !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit()) {
                if let Ok(n) = t.parse::<u64>() {
                    return Ok(GRef::Id(n));
                }
            }
            Err(format!("`{}` is not a GUID (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx) or an id", s))
        }
        Value::Num(Num::U(u)) => Ok(GRef::Id(*u)),
        Value::Num(Num::I(i)) => Err(format!("{} is not an element id", i)),
        Value::Num(Num::F(f)) => {
            if *f >= 0.0 && f.fract() == 0.0 && *f < 18446744073709551616.0 {
                Ok(GRef::Id(*f as u64))
            } else {
                Err(format!("{} is not an element id", f))
            }
        }
        _ => Err(invalid(v, "an element's GUID, or its id")),
    }
}

/// A GUID as the original takes one (hyphenated, maybe in braces, any case): one whose first
/// 64 bits are all zero is how it writes an element's id, so not a GUID.
pub fn real_guid(s: &str) -> Option<String> {
    let g = crate::structure::members::read::parse_guid(s)?;
    let hi: String = g.chars().filter(|c| *c != '-').take(16).collect();
    if hi.bytes().all(|b| b == b'0') {
        None
    } else {
        Some(g)
    }
}

/// Reads a struct: a map key by key in name order (`field` reading each; unknown keys refused),
/// then the first of `required` it lacks; or a sequence of its `fields` in order (the first
/// `required` ones needed).
fn de_struct(
    v: &Value,
    name: &str,
    fields: &[&str],
    required: &[&str],
    field: &mut dyn FnMut(&str, &Value) -> DeR<()>,
) -> DeR<()> {
    match v {
        Value::Obj(m) => {
            let mut keys: Vec<&(String, Value)> = m.items.iter().collect();
            keys.sort_by(|a, b| a.0.cmp(&b.0));
            let mut seen: Vec<&str> = Vec::new();
            for (k, x) in keys {
                if !fields.contains(&k.as_str()) {
                    return Err(format!("unknown field `{}`, expected {}", k, one_of(fields)));
                }
                field(k, x)?;
                seen.push(k);
            }
            for r in fields {
                if required.contains(r) && !seen.contains(r) {
                    return Err(format!("missing field `{}`", r));
                }
            }
            Ok(())
        }
        Value::Arr(a) => {
            for (i, f) in fields.iter().enumerate() {
                match a.get(i) {
                    Some(x) => field(f, x)?,
                    None => {
                        if required.contains(f) {
                            return Err(format!("invalid length {}, expected struct {} with {} elements", a.len(), name, fields.len()));
                        }
                    }
                }
            }
            if a.len() > fields.len() {
                return Err(format!("invalid length {}, expected fewer elements in array", a.len()));
            }
            Ok(())
        }
        _ => Err(invalid(v, &format!("struct {}", name))),
    }
}

// ---------------------------------------------------------------- the parts

pub const PARAM_FIELDS: &[&str] = &["name", "kind", "instance", "value", "formula"];

pub fn de_param(v: &Value) -> DeR<Param> {
    let mut p = Param { name: String::new(), kind: Kind::Length, instance: false, value: Value::Null, formula: None };
    de_struct(v, "Parameter", PARAM_FIELDS, &["name"], &mut |k, x| {
        match k {
            "name" => p.name = de_string(x)?,
            "kind" => p.kind = Kind::parse(&de_variant(x, KINDS)?).unwrap(),
            "instance" => p.instance = de_bool(x)?,
            "value" => p.value = x.clone(),
            _ => p.formula = de_opt(x, de_string)?,
        }
        Ok(())
    })?;
    Ok(p)
}

fn de_circle(v: &Value) -> DeR<Circle> {
    let (mut centre, mut radius) = (None, None);
    de_struct(v, "Circle", &["centre", "radius"], &["centre", "radius"], &mut |k, x| {
        match k {
            "centre" => centre = Some(de_point(x)?),
            _ => radius = Some(de_expr(x)?),
        }
        Ok(())
    })?;
    Ok(Circle { centre: centre.unwrap(), radius: radius.unwrap() })
}

fn de_mesh(v: &Value) -> DeR<Vec<[[f64; 3]; 3]>> {
    de_seq(v, &|t: &Value| {
        let pts = de_array(t, 3, &|p: &Value| {
            let c = de_array(p, 3, &de_f64)?;
            Ok([c[0], c[1], c[2]])
        })?;
        Ok([pts[0], pts[1], pts[2]])
    })
}

pub const FORM_FIELDS: &[&str] =
    &["id", "guid", "plane", "profile", "circle", "from", "to", "axis", "void", "material", "visible", "mesh"];

pub fn de_form(v: &Value) -> DeR<Form> {
    let mut f = Form::default();
    de_struct(v, "Form", FORM_FIELDS, &[], &mut |k, x| {
        match k {
            "id" => f.id = Some(de_u64(x)?).filter(|n| *n != 0),
            "guid" => f.guid = Some(de_gref(x)?).filter(|g| *g != GRef::Id(0)),
            "plane" => f.plane = Plane::parse(&de_variant(x, PLANES)?).unwrap(),
            "profile" => f.profile = de_points(x)?,
            "circle" => f.circle = de_opt(x, de_circle)?,
            "from" => f.from = de_expr(x)?,
            "to" => f.to = de_expr(x)?,
            "axis" => {
                f.axis = de_opt(x, |a| {
                    let pts = de_array(a, 2, &de_point)?;
                    let mut it = pts.into_iter();
                    Ok([it.next().unwrap(), it.next().unwrap()])
                })?
            }
            "void" => f.void = de_bool(x)?,
            "material" => f.material = de_string(x)?,
            "visible" => f.visible = de_opt(x, de_expr)?,
            _ => f.mesh = de_mesh(x)?,
        }
        Ok(())
    })?;
    Ok(f)
}

fn de_arc(v: &Value) -> DeR<Arc> {
    let (mut centre, mut radius, mut from, mut to) = (None, None, Expr::zero(), None);
    de_struct(v, "Arc", &["centre", "radius", "from", "to"], &["centre", "radius", "to"], &mut |k, x| {
        match k {
            "centre" => centre = Some(de_point(x)?),
            "radius" => radius = Some(de_expr(x)?),
            "from" => from = de_expr(x)?,
            _ => to = Some(de_expr(x)?),
        }
        Ok(())
    })?;
    Ok(Arc { centre: centre.unwrap(), radius: radius.unwrap(), from, to: to.unwrap() })
}

fn de_text(v: &Value) -> DeR<Text> {
    let (mut at, mut height, mut value, mut align) = (None, None, None, Align::Left);
    de_struct(v, "Text", &["at", "height", "value", "align"], &["at", "height", "value"], &mut |k, x| {
        match k {
            "at" => at = Some(de_point(x)?),
            "height" => height = Some(de_expr(x)?),
            "value" => value = Some(de_string(x)?),
            _ => align = Align::parse(&de_variant(x, ALIGNS)?).unwrap(),
        }
        Ok(())
    })?;
    Ok(Text { at: at.unwrap(), height: height.unwrap(), value: value.unwrap(), align })
}

fn de_dot(v: &Value) -> DeR<Dot> {
    let (mut centre, mut radius) = (None, None);
    de_struct(v, "Dot", &["centre", "radius"], &["centre", "radius"], &mut |k, x| {
        match k {
            "centre" => centre = Some(de_point(x)?),
            _ => radius = Some(de_expr(x)?),
        }
        Ok(())
    })?;
    Ok(Dot { centre: centre.unwrap(), radius: radius.unwrap() })
}

pub const SYMBOL_FIELDS: &[&str] = &["id", "guid", "line", "arc", "text", "dot", "visible"];

pub fn de_symbol(v: &Value) -> DeR<Symbol> {
    let mut s = Symbol::default();
    de_struct(v, "Symbol", SYMBOL_FIELDS, &[], &mut |k, x| {
        match k {
            "id" => s.id = Some(de_u64(x)?).filter(|n| *n != 0),
            "guid" => s.guid = Some(de_gref(x)?).filter(|g| *g != GRef::Id(0)),
            "line" => s.line = de_points(x)?,
            "arc" => s.arc = de_opt(x, de_arc)?,
            "text" => s.text = de_opt(x, de_text)?,
            "dot" => s.dot = de_opt(x, de_dot)?,
            _ => s.visible = de_opt(x, de_expr)?,
        }
        Ok(())
    })?;
    Ok(s)
}

fn de_load(v: &Value) -> DeR<Load> {
    let fail = || "data did not match any variant of untagged enum Load".to_string();
    match v {
        Value::Num(_) | Value::Str(_) => Ok(Load::One(de_expr(v).map_err(|_| fail())?)),
        Value::Arr(a) => {
            let mut out = Vec::with_capacity(a.len());
            for x in a {
                out.push(de_expr(x).map_err(|_| fail())?);
            }
            Ok(Load::PerPole(out))
        }
        _ => Err(fail()),
    }
}

pub const CONNECTOR_FIELDS: &[&str] =
    &["id", "guid", "kind", "system", "poles", "voltage", "load_va", "power_factor", "classification"];

pub fn de_connector(v: &Value) -> DeR<Connector> {
    let mut c = Connector {
        id: None,
        guid: None,
        kind: ConnKind::Power,
        system: System::Balanced,
        poles: 1,
        voltage: Expr::zero(),
        load_va: Load::One(Expr::zero()),
        power_factor: Expr::Num(1.0),
        classification: String::new(),
    };
    de_struct(v, "Connector", CONNECTOR_FIELDS, &["kind", "system"], &mut |k, x| {
        match k {
            "id" => c.id = Some(de_u64(x)?).filter(|n| *n != 0),
            "guid" => c.guid = Some(de_gref(x)?).filter(|g| *g != GRef::Id(0)),
            "kind" => c.kind = ConnKind::parse(&de_variant(x, CONN_KINDS)?).unwrap(),
            "system" => c.system = System::parse(&de_variant(x, SYSTEMS)?).unwrap(),
            "poles" => c.poles = de_u8(x)?,
            "voltage" => c.voltage = de_expr(x)?,
            "load_va" => c.load_va = de_load(x)?,
            "power_factor" => c.power_factor = de_expr(x)?,
            _ => c.classification = de_string(x)?,
        }
        Ok(())
    })?;
    Ok(c)
}

/// `types`: {type: {parameter: value} | null}, null taking a type away; a type's values with
/// their nulls (a null takes a value away).
pub fn de_types(v: &Value) -> DeR<Vec<(String, Option<Map>)>> {
    match v {
        Value::Obj(m) => {
            let mut keys: Vec<&(String, Value)> = m.items.iter().collect();
            keys.sort_by(|a, b| a.0.cmp(&b.0));
            let mut out = Vec::with_capacity(keys.len());
            for (k, x) in keys {
                match x {
                    Value::Null => out.push((k.clone(), None)),
                    Value::Obj(vals) => {
                        let mut t = Map::new();
                        for (pk, pv) in vals.iter() {
                            t.insert_sorted(pk, pv.clone());
                        }
                        out.push((k.clone(), Some(t)));
                    }
                    other => return Err(invalid(other, "a map")),
                }
            }
            Ok(out)
        }
        _ => Err(invalid(v, "a map")),
    }
}

/// `category`: one of the original's.
pub fn de_category(v: &Value) -> DeR<String> {
    de_variant(v, CATEGORIES)
}

