//! Working a family out for one of its types (and a component's own values): each parameter's
//! value, a formula reading others through theirs, and a form's or a symbol's sizes.

use super::model::*;
use crate::json::{Map, Value};
use crate::structure::formula::{self, ParseError};

/// The most formulas in a row that read one another.
pub const MAX_CHAIN: usize = 16;

/// The largest number a size may come to (mm).
pub const MAX_COORD: f64 = 1e9;

/// The wall thickness a door's or a window's family is worked out in when it stands in none.
pub const DEFAULT_WALL: f64 = 200.0;

/// The name a hosted family's formulas read its wall's thickness by.
pub const WALL_THICKNESS: &str = "Wall Thickness";

/// A parameter's value worked out: a number (a yes as 1, a no as 0), or a material's name.
#[derive(Clone, Debug, PartialEq)]
pub enum PVal {
    Num(f64),
    Mat(String),
}

impl PVal {
    pub fn value(&self) -> Value {
        match self {
            PVal::Num(x) => Value::f(*x),
            PVal::Mat(s) => Value::s(s),
        }
    }
    pub fn num(&self) -> f64 {
        match self {
            PVal::Num(x) => *x,
            PVal::Mat(_) => 0.0,
        }
    }
}

/// A number as the original says it in its messages (Rust's `{}` of an f64).
pub fn disp(x: f64) -> String {
    format!("{}", x)
}

/// A family worked out for one type: the values its type gives (and a component's over them).
pub struct Eval<'a> {
    pub fam: &'a Family,
    /// What's given: the type's values, a component's instance values over them, by name.
    pub given: Map,
    /// A hosted family's wall thickness.
    pub wall: Option<f64>,
}

impl<'a> Eval<'a> {
    /// For a type (by name; none gives the parameters' own values), with a component's values
    /// over its instance parameters, and a hosted family's wall thickness (200 when none).
    pub fn new(fam: &'a Family, type_name: Option<&str>, instance: Option<&Map>, wall: Option<f64>) -> Eval<'a> {
        let mut given = Map::new();
        if let Some(t) = type_name.and_then(|n| fam.type_values(n)) {
            for (k, v) in t.iter() {
                if !v.is_null() {
                    given.insert(k, v.clone());
                }
            }
        }
        if let Some(inst) = instance {
            for (k, v) in inst.iter() {
                if v.is_null() {
                    continue;
                }
                if fam.param(k).map(|p| p.instance).unwrap_or(false) {
                    given.insert(k, v.clone());
                }
            }
        }
        let wall = if fam.hosted() { Some(wall.unwrap_or(DEFAULT_WALL)) } else { None };
        Eval { fam, given, wall }
    }

    /// A parameter's plain value (no formula): what's given, else its own; a material's name.
    fn plain(&self, p: &Param) -> PVal {
        let v = self.given.get(&p.name).unwrap_or(&p.value);
        match p.kind {
            Kind::Material => PVal::Mat(v.as_str().unwrap_or("").to_string()),
            _ => PVal::Num(match v {
                Value::Num(n) => n.as_f64(),
                Value::Bool(b) => {
                    if *b {
                        1.0
                    } else {
                        0.0
                    }
                }
                _ => 0.0,
            }),
        }
    }

    /// A name as a formula reads it, with the formulas being worked out (`stack`).
    fn read(&self, name: &str, stack: &mut Vec<String>) -> Result<f64, String> {
        if let Some(w) = self.wall {
            if name == WALL_THICKNESS {
                return Ok(w);
            }
        }
        let p = match self.fam.param(name) {
            Some(p) => p,
            None => return Err(format!("`{}` isn't one of its parameters", name)),
        };
        if p.kind == Kind::Material {
            return Err(format!("`{}` is a material, not a number", name));
        }
        match &p.formula {
            None => Ok(self.plain(p).num()),
            Some(f) => {
                if stack.iter().any(|s| s == name) {
                    return Err(format!("`{}`'s formula comes back to itself", name));
                }
                if stack.len() >= MAX_CHAIN {
                    return Err(format!(
                        "`{}` takes from formulas taking from more than {} others in a row: nested too deep",
                        name, MAX_CHAIN
                    ));
                }
                stack.push(name.to_string());
                let r = self.formula(f, stack);
                stack.pop();
                r.map_err(|e| format!("parameter `{}`: {}", name, e))
            }
        }
    }

    /// A formula's text worked out: "formula `…`: why" when it can't be.
    fn formula(&self, text: &str, stack: &mut Vec<String>) -> Result<f64, String> {
        let f = match formula::parse(text) {
            Ok(f) => f,
            Err(ParseError::Empty) => return Err("a formula is empty".into()),
            Err(ParseError::Syntax(m)) => return Err(format!("formula `{}`: {}", text, m)),
        };
        f.eval(&mut |n: &str| self.read(n, stack)).map_err(|e| format!("formula `{}`: {}", text, e))
    }

    /// A parameter's value worked out (its formula, if it has one), as `values` shows it.
    pub fn param(&self, p: &Param) -> Result<PVal, String> {
        match (&p.formula, p.kind) {
            (Some(f), k) if k != Kind::Material => {
                let mut stack = vec![p.name.clone()];
                let v = self.formula(f, &mut stack).map_err(|e| format!("parameter `{}`: {}", p.name, e))?;
                Ok(PVal::Num(v))
            }
            _ => Ok(self.plain(p)),
        }
    }

    /// A parameter's value by name (a hosted family's `Wall Thickness` too).
    pub fn value_of(&self, name: &str) -> Option<Result<PVal, String>> {
        if let Some(w) = self.wall {
            if name == WALL_THICKNESS {
                return Some(Ok(PVal::Num(w)));
            }
        }
        self.fam.param(name).map(|p| self.param(p))
    }

    /// Every parameter's value, in their order (and a hosted family's `Wall Thickness` last).
    pub fn values(&self) -> Result<Vec<(String, PVal)>, String> {
        let mut out = Vec::with_capacity(self.fam.parameters.len() + 1);
        for p in &self.fam.parameters {
            out.push((p.name.clone(), self.param(p)?));
        }
        if let Some(w) = self.wall {
            out.push((WALL_THICKNESS.to_string(), PVal::Num(w)));
        }
        Ok(out)
    }

    /// A size: a number as it is, a formula worked out ("formula `…`: why").
    pub fn expr(&self, e: &Expr) -> Result<f64, String> {
        match e {
            Expr::Num(x) => Ok(*x),
            Expr::Text(s) => self.formula(s, &mut Vec::new()),
        }
    }

    /// A size that must be usable: finite and within 1000 km.
    pub fn usable(&self, e: &Expr) -> Result<f64, String> {
        let x = self.expr(e)?;
        if !(x.is_finite() && x.abs() <= MAX_COORD) {
            return Err(format!("{} is not a usable number", disp(x)));
        }
        Ok(x)
    }

    pub fn point(&self, p: &Pt) -> Result<[f64; 2], String> {
        Ok([self.usable(&p[0])?, self.usable(&p[1])?])
    }

    /// Whether a part is there: its `visible` worked out, not zero (none, it is).
    pub fn visible(&self, v: &Option<Expr>) -> Result<bool, String> {
        match v {
            None => Ok(true),
            Some(e) => Ok(self.usable(e)? != 0.0),
        }
    }
}

/// A family's values for a type as `family` and `elements` show them: {name: number or
/// material name}, a hosted family's `Wall Thickness` among them.
pub fn values_view(vals: &[(String, PVal)]) -> Value {
    let mut m = Map::new();
    for (k, v) in vals {
        m.insert_sorted(k, v.value());
    }
    Value::Obj(m)
}

//! A family's forms as solids: a profile (or a circle, 32 sides) swept across its plane or
//! turned about an axis (32 steps to a turn), or triangles as a file brings them; their boxes
//! before any void cuts them; and voids cutting the solid forms listed before them (convex
//! polygons in binary space partitions, as `csg.js` does it).

pub type V3 = [f64; 3];

/// Sides of a circle, steps of a full turn.
pub const SEGMENTS: usize = 32;

fn sub(a: V3, b: V3) -> V3 {
    [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
}
fn add(a: V3, b: V3) -> V3 {
    [a[0] + b[0], a[1] + b[1], a[2] + b[2]]
}
fn scale(a: V3, s: f64) -> V3 {
    [a[0] * s, a[1] * s, a[2] * s]
}
fn dot(a: V3, b: V3) -> f64 {
    a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
}
fn cross(a: V3, b: V3) -> V3 {
    [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]
}
fn len(a: V3) -> f64 {
    dot(a, a).sqrt()
}
fn lerp(a: V3, b: V3, t: f64) -> V3 {
    add(a, scale(sub(b, a), t))
}

/// A box: its least and greatest corners.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Bbox {
    pub min: V3,
    pub max: V3,
}

impl Bbox {
    pub fn of(points: impl IntoIterator<Item = V3>) -> Option<Bbox> {
        let mut b: Option<Bbox> = None;
        for p in points {
            b = Some(match b {
                None => Bbox { min: p, max: p },
                Some(mut x) => {
                    for i in 0..3 {
                        x.min[i] = x.min[i].min(p[i]);
                        x.max[i] = x.max[i].max(p[i]);
                    }
                    x
                }
            });
        }
        b
    }
    /// Whether two boxes share some volume (touching doesn't count).
    pub fn overlaps(&self, o: &Bbox) -> bool {
        (0..3).all(|i| self.min[i] < o.max[i] && o.min[i] < self.max[i])
    }
}

/// A closed surface: convex polygons, each turned out (counter-clockwise seen from outside).
#[derive(Clone, Debug, Default)]
pub struct Solid {
    pub polys: Vec<Vec<V3>>,
}

impl Solid {
    pub fn bbox(&self) -> Option<Bbox> {
        Bbox::of(self.polys.iter().flat_map(|p| p.iter().copied()))
    }
    /// Its surface as triangles, turned out.
    pub fn triangles(&self) -> Vec<[V3; 3]> {
        let mut out = Vec::new();
        for p in &self.polys {
            for i in 1..p.len().saturating_sub(1) {
                out.push([p[0], p[i], p[i + 1]]);
            }
        }
        out
    }
    /// Its volume (negative where its polygons are turned in).
    pub fn volume(&self) -> f64 {
        self.triangles().iter().map(|t| dot(t[0], cross(t[1], t[2])) / 6.0).sum()
    }
    fn flip(&mut self) {
        for p in &mut self.polys {
            p.reverse();
        }
    }
    /// Moved by a map of points (one that mirrors turns the polygons back out).
    pub fn mapped(&self, f: &dyn Fn(V3) -> V3, mirrors: bool) -> Solid {
        let mut s = Solid { polys: self.polys.iter().map(|p| p.iter().map(|v| f(*v)).collect()).collect() };
        if mirrors {
            s.flip();
        }
        s
    }
}

/// The signed area of a profile (counter-clockwise positive).
pub fn area(p: &[[f64; 2]]) -> f64 {
    let n = p.len();
    let mut a = 0.0;
    for i in 0..n {
        let j = (i + 1) % n;
        a += p[i][0] * p[j][1] - p[j][0] * p[i][1];
    }
    a / 2.0
}

/// A circle as the polygon the original draws it with.
pub fn circle(c: [f64; 2], r: f64) -> Vec<[f64; 2]> {
    (0..SEGMENTS)
        .map(|k| {
            let t = 2.0 * std::f64::consts::PI * k as f64 / SEGMENTS as f64;
            [c[0] + r * t.cos(), c[1] + r * t.sin()]
        })
        .collect()
}

/// A profile without the points that repeat the one before them (and the last that repeats
/// the first), counter-clockwise.
fn clean(p: &[[f64; 2]]) -> Vec<[f64; 2]> {
    let mut out: Vec<[f64; 2]> = Vec::with_capacity(p.len());
    for q in p {
        if out.last().map(|l| (l[0] - q[0]).abs() < 1e-9 && (l[1] - q[1]).abs() < 1e-9).unwrap_or(false) {
            continue;
        }
        out.push(*q);
    }
    while out.len() > 1 {
        let (f, l) = (out[0], out[out.len() - 1]);
        if (f[0] - l[0]).abs() < 1e-9 && (f[1] - l[1]).abs() < 1e-9 {
            out.pop();
        } else {
            break;
        }
    }
    if area(&out) < 0.0 {
        out.reverse();
    }
    out
}

/// A simple polygon (counter-clockwise) cut into triangles by its ears.
pub fn triangulate(p: &[[f64; 2]]) -> Vec<[usize; 3]> {
    let n = p.len();
    if n < 3 {
        return Vec::new();
    }
    let mut idx: Vec<usize> = (0..n).collect();
    let mut out = Vec::with_capacity(n - 2);
    let cross2 = |a: [f64; 2], b: [f64; 2], c: [f64; 2]| (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    let inside = |q: [f64; 2], a: [f64; 2], b: [f64; 2], c: [f64; 2]| {
        cross2(a, b, q) >= 0.0 && cross2(b, c, q) >= 0.0 && cross2(c, a, q) >= 0.0
    };
    let mut guard = 0;
    while idx.len() > 3 && guard < n * n {
        guard += 1;
        let m = idx.len();
        let mut cut = None;
        for i in 0..m {
            let (ia, ib, ic) = (idx[(i + m - 1) % m], idx[i], idx[(i + 1) % m]);
            let (a, b, c) = (p[ia], p[ib], p[ic]);
            if cross2(a, b, c) <= 0.0 {
                continue;
            }
            let blocked = idx.iter().any(|&j| j != ia && j != ib && j != ic && inside(p[j], a, b, c) && p[j] != a && p[j] != b && p[j] != c);
            if !blocked {
                cut = Some(i);
                break;
            }
        }
        // a polygon no ear can be cut from (it crosses itself): cut the first corner anyway
        let i = cut.unwrap_or(0);
        let m = idx.len();
        out.push([idx[(i + m - 1) % m], idx[i], idx[(i + 1) % m]]);
        idx.remove(i);
    }
    if idx.len() == 3 {
        out.push([idx[0], idx[1], idx[2]]);
    }
    out
}

/// The sketch planes: a profile's (a, b) and the sweep's s in the family's x, y, z.
pub fn place(plane: super::model::Plane, a: f64, b: f64, s: f64) -> V3 {
    use super::model::Plane::*;
    match plane {
        XY => [a, b, s],
        XZ => [a, s, b],
        YZ => [s, a, b],
    }
}

fn sweep_dir(plane: super::model::Plane) -> V3 {
    place(plane, 0.0, 0.0, 1.0)
}

fn orient(poly: Vec<V3>, out: V3) -> Vec<V3> {
    if poly.len() < 3 {
        return poly;
    }
    let mut n = [0.0; 3];
    for i in 0..poly.len() {
        let (a, b) = (poly[i], poly[(i + 1) % poly.len()]);
        n[0] += (a[1] - b[1]) * (a[2] + b[2]);
        n[1] += (a[2] - b[2]) * (a[0] + b[0]);
        n[2] += (a[0] - b[0]) * (a[1] + b[1]);
    }
    if dot(n, out) < 0.0 {
        let mut p = poly;
        p.reverse();
        p
    } else {
        poly
    }
}

/// A profile swept from `from` to `to` across its plane.
pub fn extrude(plane: super::model::Plane, profile: &[[f64; 2]], from: f64, to: f64) -> Solid {
    let p = clean(profile);
    let mut s = Solid::default();
    if p.len() < 3 {
        return s;
    }
    let d = sweep_dir(plane);
    let tris = triangulate(&p);
    for t in &tris {
        let top: Vec<V3> = t.iter().map(|&i| place(plane, p[i][0], p[i][1], to)).collect();
        s.polys.push(orient(top, d));
        let bot: Vec<V3> = t.iter().map(|&i| place(plane, p[i][0], p[i][1], from)).collect();
        s.polys.push(orient(bot, scale(d, -1.0)));
    }
    let n = p.len();
    for i in 0..n {
        let (a, b) = (p[i], p[(i + 1) % n]);
        // outward of a counter-clockwise profile's edge: to its right
        let out2 = [b[1] - a[1], -(b[0] - a[0])];
        let out = sub(place(plane, out2[0], out2[1], 0.0), place(plane, 0.0, 0.0, 0.0));
        let quad = vec![place(plane, a[0], a[1], from), place(plane, b[0], b[1], from), place(plane, b[0], b[1], to), place(plane, a[0], a[1], to)];
        s.polys.push(orient(quad, out));
    }
    s
}

/// Rotates `p` about the line through `o` along unit `u` by `t` radians (right-handed).
fn rotate(p: V3, o: V3, u: V3, t: f64) -> V3 {
    let v = sub(p, o);
    let (c, sn) = (t.cos(), t.sin());
    let k = dot(u, v);
    let r = add(add(scale(v, c), scale(cross(u, v), sn)), scale(u, k * (1.0 - c)));
    add(o, r)
}

/// How many steps a turn of `deg` degrees takes.
pub fn steps(deg: f64) -> usize {
    ((deg.abs() / 360.0 * SEGMENTS as f64).ceil() as usize).max(1)
}

/// A profile turned about an axis in its plane from `from` to `to` degrees.
pub fn revolve(plane: super::model::Plane, profile: &[[f64; 2]], axis: [[f64; 2]; 2], from: f64, to: f64) -> Solid {
    let p = clean(profile);
    let mut s = Solid::default();
    if p.len() < 3 {
        return s;
    }
    let o = place(plane, axis[0][0], axis[0][1], 0.0);
    let e = sub(place(plane, axis[1][0], axis[1][1], 0.0), o);
    let l = len(e);
    if l == 0.0 {
        return s;
    }
    let u = scale(e, 1.0 / l);
    let span = to - from;
    let full = span >= 360.0;
    let n_steps = steps(span);
    let pts3: Vec<V3> = p.iter().map(|q| place(plane, q[0], q[1], 0.0)).collect();
    let ring = |k: usize| -> Vec<V3> {
        let t = (from + span * k as f64 / n_steps as f64).to_radians();
        pts3.iter().map(|q| rotate(*q, o, u, t)).collect()
    };
    let rings: Vec<Vec<V3>> = (0..=n_steps).map(ring).collect();
    let n = p.len();
    let same = |a: V3, b: V3| len(sub(a, b)) < 1e-9;
    for k in 0..n_steps {
        let (r0, r1) = (&rings[k], if full && k + 1 == n_steps { &rings[0] } else { &rings[k + 1] });
        for i in 0..n {
            let j = (i + 1) % n;
            let mut quad = vec![r0[i], r0[j], r1[j], r1[i]];
            quad.dedup_by(|a, b| same(*a, *b));
            if quad.len() > 1 && same(quad[0], quad[quad.len() - 1]) {
                quad.pop();
            }
            if quad.len() >= 3 {
                s.polys.push(quad);
            }
        }
    }
    if !full {
        let tris = triangulate(&p);
        for t in &tris {
            // the start's cap runs against the sides' first edges, the end's with their last
            s.polys.push(vec![rings[0][t[2]], rings[0][t[1]], rings[0][t[0]]]);
            s.polys.push(vec![rings[n_steps][t[0]], rings[n_steps][t[1]], rings[n_steps][t[2]]]);
        }
    }
    if s.volume() < 0.0 {
        s.flip();
    }
    s
}

/// Triangles as a file brings them.
pub fn mesh(tris: &[[[f64; 3]; 3]]) -> Solid {
    Solid { polys: tris.iter().map(|t| t.to_vec()).collect() }
}

// ---------------------------------------------------------------- cutting (csg.js's BSP)

const EPS: f64 = 1e-5;

#[derive(Clone, Copy, Debug)]
struct Plane {
    n: V3,
    w: f64,
}

impl Plane {
    fn of(p: &[V3]) -> Option<Plane> {
        // Newell's normal: robust for any convex polygon
        let mut n = [0.0; 3];
        for i in 0..p.len() {
            let (a, b) = (p[i], p[(i + 1) % p.len()]);
            n[0] += (a[1] - b[1]) * (a[2] + b[2]);
            n[1] += (a[2] - b[2]) * (a[0] + b[0]);
            n[2] += (a[0] - b[0]) * (a[1] + b[1]);
        }
        let l = len(n);
        if !(l > 1e-12) || !l.is_finite() {
            return None;
        }
        let n = scale(n, 1.0 / l);
        Some(Plane { n, w: dot(n, p[0]) })
    }
    fn flip(&mut self) {
        self.n = scale(self.n, -1.0);
        self.w = -self.w;
    }
}

#[derive(Clone, Debug)]
struct Poly {
    v: Vec<V3>,
    plane: Plane,
}

impl Poly {
    fn new(v: Vec<V3>) -> Option<Poly> {
        let plane = Plane::of(&v)?;
        Some(Poly { v, plane })
    }
    fn flip(&mut self) {
        self.v.reverse();
        self.plane.flip();
    }
}

const COPLANAR: u8 = 0;
const FRONT: u8 = 1;
const BACK: u8 = 2;
const SPANNING: u8 = 3;

fn split(plane: &Plane, poly: &Poly, cf: &mut Vec<Poly>, cb: &mut Vec<Poly>, f: &mut Vec<Poly>, b: &mut Vec<Poly>) {
    let mut ptype = 0u8;
    let types: Vec<u8> = poly
        .v
        .iter()
        .map(|v| {
            let t = dot(plane.n, *v) - plane.w;
            let ty = if t < -EPS {
                BACK
            } else if t > EPS {
                FRONT
            } else {
                COPLANAR
            };
            ptype |= ty;
            ty
        })
        .collect();
    match ptype {
        COPLANAR => {
            if dot(plane.n, poly.plane.n) > 0.0 {
                cf.push(poly.clone())
            } else {
                cb.push(poly.clone())
            }
        }
        FRONT => f.push(poly.clone()),
        BACK => b.push(poly.clone()),
        _ => {
            let (mut fv, mut bv) = (Vec::new(), Vec::new());
            let n = poly.v.len();
            for i in 0..n {
                let j = (i + 1) % n;
                let (ti, tj) = (types[i], types[j]);
                let (vi, vj) = (poly.v[i], poly.v[j]);
                if ti != BACK {
                    fv.push(vi);
                }
                if ti != FRONT {
                    bv.push(vi);
                }
                if (ti | tj) == SPANNING {
                    let t = (plane.w - dot(plane.n, vi)) / dot(plane.n, sub(vj, vi));
                    let v = lerp(vi, vj, t);
                    fv.push(v);
                    bv.push(v);
                }
            }
            if fv.len() >= 3 {
                f.push(Poly { v: fv, plane: poly.plane });
            }
            if bv.len() >= 3 {
                b.push(Poly { v: bv, plane: poly.plane });
            }
        }
    }
}

#[derive(Default)]
struct Node {
    plane: Option<Plane>,
    front: Option<Box<Node>>,
    back: Option<Box<Node>>,
    polys: Vec<Poly>,
}

/// How much work cutting may take before the shape is called too complex.
const BUDGET: usize = 2_000_000;

impl Node {
    fn new(polys: Vec<Poly>, budget: &mut usize) -> Node {
        let mut n = Node::default();
        n.build(polys, budget);
        n
    }
    fn invert(&mut self) {
        let mut stack: Vec<&mut Node> = vec![self];
        while let Some(n) = stack.pop() {
            for p in &mut n.polys {
                p.flip();
            }
            if let Some(pl) = &mut n.plane {
                pl.flip();
            }
            std::mem::swap(&mut n.front, &mut n.back);
            if let Some(f) = n.front.as_deref_mut() {
                stack.push(f);
            }
            if let Some(b) = n.back.as_deref_mut() {
                stack.push(b);
            }
        }
    }
    fn clip_polygons(&self, polys: Vec<Poly>, budget: &mut usize) -> Vec<Poly> {
        let mut out = Vec::new();
        let mut work: Vec<(&Node, Vec<Poly>)> = vec![(self, polys)];
        while let Some((n, ps)) = work.pop() {
            let Some(pl) = &n.plane else {
                out.extend(ps);
                continue;
            };
            *budget = budget.saturating_sub(ps.len() + 1);
            let (mut f, mut b) = (Vec::new(), Vec::new());
            for p in &ps {
                let (mut cf, mut cb) = (Vec::new(), Vec::new());
                split(pl, p, &mut cf, &mut cb, &mut f, &mut b);
                f.extend(cf);
                b.extend(cb);
            }
            match &n.front {
                Some(fr) => work.push((fr, f)),
                None => out.extend(f),
            }
            if let Some(bk) = &n.back {
                work.push((bk, b));
            }
        }
        out
    }
    fn clip_to(&mut self, other: &Node, budget: &mut usize) {
        let mut stack: Vec<&mut Node> = vec![self];
        while let Some(n) = stack.pop() {
            let ps = std::mem::take(&mut n.polys);
            n.polys = other.clip_polygons(ps, budget);
            if let Some(f) = n.front.as_deref_mut() {
                stack.push(f);
            }
            if let Some(b) = n.back.as_deref_mut() {
                stack.push(b);
            }
        }
    }
    fn all(&self) -> Vec<Poly> {
        let mut out = Vec::new();
        let mut stack: Vec<&Node> = vec![self];
        while let Some(n) = stack.pop() {
            out.extend(n.polys.iter().cloned());
            if let Some(f) = &n.front {
                stack.push(f);
            }
            if let Some(b) = &n.back {
                stack.push(b);
            }
        }
        out
    }
    fn build(&mut self, polys: Vec<Poly>, budget: &mut usize) {
        let mut work: Vec<(*mut Node, Vec<Poly>)> = vec![(self as *mut Node, polys)];
        while let Some((np, ps)) = work.pop() {
            if ps.is_empty() || *budget == 0 {
                continue;
            }
            *budget = budget.saturating_sub(ps.len());
            // SAFETY: each node is reached once, from its parent's own box, while the tree grows
            let n = unsafe { &mut *np };
            if n.plane.is_none() {
                n.plane = Some(ps[0].plane);
            }
            let pl = n.plane.unwrap();
            let (mut f, mut b) = (Vec::new(), Vec::new());
            let (mut cf, mut cb) = (Vec::new(), Vec::new());
            for p in &ps {
                split(&pl, p, &mut cf, &mut cb, &mut f, &mut b);
            }
            n.polys.extend(cf);
            n.polys.extend(cb);
            if !f.is_empty() {
                let fr = n.front.get_or_insert_with(|| Box::new(Node::default()));
                work.push((fr.as_mut() as *mut Node, f));
            }
            if !b.is_empty() {
                let bk = n.back.get_or_insert_with(|| Box::new(Node::default()));
                work.push((bk.as_mut() as *mut Node, b));
            }
        }
    }
}

fn polys_of(s: &Solid) -> Vec<Poly> {
    s.polys.iter().filter_map(|p| Poly::new(p.clone())).collect()
}

/// `a` with `b` taken out of it; None when it's too much work.
pub fn subtract(a: &Solid, b: &Solid) -> Option<Solid> {
    let mut budget = BUDGET;
    let mut na = Node::new(polys_of(a), &mut budget);
    let mut nb = Node::new(polys_of(b), &mut budget);
    na.invert();
    na.clip_to(&nb, &mut budget);
    nb.clip_to(&na, &mut budget);
    nb.invert();
    nb.clip_to(&na, &mut budget);
    nb.invert();
    let rest = nb.all();
    na.build(rest, &mut budget);
    na.invert();
    if budget == 0 {
        return None;
    }
    Some(Solid { polys: na.all().into_iter().map(|p| p.v).collect() })
}

//! What the original finds wrong with a family (`Family::problems`): every formula read at
//! once (each name it reads that the family lacks, syntax, functions), then the first thing its
//! rules refuse (`Family::check`, the model's rule too), and the warnings its geometry gives, each
//! said once for the types it holds in (`(in type `A`, `B`)`).

use super::eval::{disp, Eval, MAX_COORD, WALL_THICKNESS};
use super::geom::{self, Bbox, Solid};
use super::model::*;
use crate::json::Value;
use crate::structure::formula::{self, ParseError, MAX_LEN};

/// The most parameters, corners of a profile and points of a symbol's line.
pub const MAX_PARAMS: usize = 64;
pub const MAX_PROFILE: usize = 64;
pub const MAX_LINE: usize = 64;

/// The most characters a symbol's lettered text has.
pub const MAX_TEXT: usize = 256;

/// The longest name a parameter or a type has.
pub const MAX_NAME: usize = 256;

/// Whether a parameter's name is one: a letter (or `_`) first, then letters, digits, `_` and
/// spaces, up to 256 characters.
pub fn name_ok(name: &str) -> bool {
    if name.chars().count() > MAX_NAME {
        return false;
    }
    let mut cs = name.chars();
    match cs.next() {
        Some(c) if c.is_alphabetic() || c == '_' => {}
        _ => return false,
    }
    let ok = cs.all(|c| c.is_alphanumeric() || c == '_' || c == ' ');
    ok && !name.ends_with(' ')
}

// ---------------------------------------------------------------- reading every formula

/// The formulas of a form, in the order the original reads them over its definition.
fn form_formulas(f: &Form) -> Vec<&str> {
    let mut out = Vec::new();
    let mut e = |x: &Expr| {
        if let Expr::Text(s) = x {
            out.push(s.as_str());
        }
    };
    for p in &f.profile {
        e(&p[0]);
        e(&p[1]);
    }
    e(&f.from);
    e(&f.to);
    if let Some(v) = &f.visible {
        e(v);
    }
    if let Some(c) = &f.circle {
        e(&c.centre[0]);
        e(&c.centre[1]);
        e(&c.radius);
    }
    if let Some(a) = &f.axis {
        for p in a {
            e(&p[0]);
            e(&p[1]);
        }
    }
    out
}

/// A symbol's formulas the original reads over its definition (its line, `visible`, its arc).
fn symbol_read_formulas(s: &Symbol) -> Vec<&str> {
    let mut out = Vec::new();
    let mut e = |x: &Expr| {
        if let Expr::Text(t) = x {
            out.push(t.as_str());
        }
    };
    for p in &s.line {
        e(&p[0]);
        e(&p[1]);
    }
    if let Some(v) = &s.visible {
        e(v);
    }
    if let Some(a) = &s.arc {
        e(&a.centre[0]);
        e(&a.centre[1]);
        e(&a.radius);
        e(&a.from);
        e(&a.to);
    }
    out
}

/// Every formula of a symbol.
fn symbol_formulas(s: &Symbol) -> Vec<&str> {
    let mut out = symbol_read_formulas(s);
    let mut e = |x: &Expr| {
        if let Expr::Text(t) = x {
            out.push(t.as_str());
        }
    };
    if let Some(t) = &s.text {
        e(&t.at[0]);
        e(&t.at[1]);
        e(&t.height);
    }
    if let Some(d) = &s.dot {
        e(&d.centre[0]);
        e(&d.centre[1]);
        e(&d.radius);
    }
    out
}

fn connector_formulas(c: &Connector) -> Vec<&str> {
    let mut out = Vec::new();
    let mut e = |x: &Expr| {
        if let Expr::Text(t) = x {
            out.push(t.as_str());
        }
    };
    e(&c.voltage);
    match &c.load_va {
        Load::One(x) => e(x),
        Load::PerPole(v) => v.iter().for_each(&mut e),
    }
    e(&c.power_factor);
    out
}

fn too_long(s: &str) -> bool {
    s.chars().count() > MAX_LEN
}

/// What reading a formula of the family's definition finds: its syntax, its functions, each
/// name it reads that the family lacks (none for one longer than the most, which its rules say).
fn read_one(fam: &Family, text: &str, at: &str, out: &mut Vec<String>) {
    if too_long(text) {
        return;
    }
    let f = match formula::parse(text) {
        Ok(f) => f,
        Err(ParseError::Empty) => {
            out.push(format!("{}: a formula is empty", at));
            return;
        }
        Err(ParseError::Syntax(m)) => {
            out.push(format!("{}: formula `{}`: {}", at, text, m));
            return;
        }
    };
    if let Err(m) = f.check_calls() {
        out.push(format!("{}: formula `{}`: {}", at, text, m));
        return;
    }
    for n in f.names() {
        let known = fam.param(&n).is_some() || (fam.hosted() && n == WALL_THICKNESS);
        if !known {
            out.push(format!("{}: formula `{}` reads `{}`, which isn't one of its parameters", at, text, n));
        }
    }
}

/// Every formula of the family read at once.
pub fn read_formulas(fam: &Family) -> Vec<String> {
    let mut out = Vec::new();
    for p in &fam.parameters {
        if let Some(f) = &p.formula {
            read_one(fam, f, &format!("parameter `{}`", p.name), &mut out);
        }
    }
    for (i, f) in fam.forms.iter().enumerate() {
        for t in form_formulas(f) {
            read_one(fam, t, &format!("form {}", i + 1), &mut out);
        }
    }
    for (i, s) in fam.symbols.iter().enumerate() {
        for t in symbol_read_formulas(s) {
            read_one(fam, t, &format!("symbol {}", i + 1), &mut out);
        }
    }
    out
}

// ---------------------------------------------------------------- the family's rules

fn holds(kind: Kind) -> &'static str {
    match kind {
        Kind::YesNo => "yes or no",
        Kind::Material => "a material's name",
        _ => "a number",
    }
}

/// Whether a value is one a parameter of this kind holds (null is none).
fn fits(kind: Kind, v: &Value) -> bool {
    match (kind, v) {
        (_, Value::Null) => true,
        (Kind::Material, Value::Str(_)) => true,
        (Kind::YesNo, Value::Bool(_)) | (Kind::YesNo, Value::Num(_)) => true,
        (Kind::Length | Kind::Number | Kind::Angle, Value::Num(_)) => true,
        _ => false,
    }
}

fn no_material(m: &str) -> String {
    format!("material `{}` isn't in the library; add it with `material`", m)
}

/// The `{Parameter}`s a symbol's text reads, in order; Err for a `{` left open.
pub fn text_refs(value: &str) -> Result<Vec<String>, ()> {
    let mut out = Vec::new();
    let mut rest = value;
    while let Some(i) = rest.find('{') {
        let after = &rest[i + 1..];
        match after.find('}') {
            Some(j) => {
                out.push(after[..j].to_string());
                rest = &after[j + 1..];
            }
            None => return Err(()),
        }
    }
    Ok(out)
}

/// A number as a symbol's text says it: to the thousandth, as plainly as it reads.
pub fn said_number(x: f64) -> String {
    let s = format!("{:.3}", x);
    let s = if s.contains('.') { s.trim_end_matches('0').trim_end_matches('.').to_string() } else { s };
    s
}

/// The rules the family itself is held to, worked out for every type: the first refusal, as
/// the original says it (after `family `name`: `).
pub fn rules(fam: &Family, has_material: &dyn Fn(&str) -> bool) -> Result<(), String> {
    if fam.parameters.len() > MAX_PARAMS {
        return Err(format!("it has more than {} parameters", MAX_PARAMS));
    }
    if fam.types.is_empty() {
        return Err("it needs a type: add one to `types`".into());
    }
    if let Some(k) = &fam.kind {
        let kinds = kinds_of(&fam.category);
        if kinds.is_empty() {
            return Err(format!("`kind` `{}`: a family of this category has no kinds; leave `kind` out", k));
        }
        if !kinds.contains(&k.as_str()) {
            return Err(format!("`kind` is one of {}, not `{}`", kinds.join(", "), k));
        }
    }
    if fam.hosted() {
        for n in ["Width", "Height"] {
            if !fam.parameters.iter().any(|p| p.name == n && p.kind == Kind::Length) {
                return Err(format!(
                    "a door or window family needs a length parameter `{}`: the size of the opening it makes",
                    n
                ));
            }
        }
        if fam.param(WALL_THICKNESS).is_some() {
            return Err(format!(
                "`{}` is the wall's, which a door or a window reads; name the parameter otherwise",
                WALL_THICKNESS
            ));
        }
    }
    let mut seen: Vec<&str> = Vec::new();
    for p in &fam.parameters {
        if !name_ok(&p.name) {
            return Err(format!(
                "parameter `{}`: a name starts with a letter and holds letters, digits, `_` and spaces, up to {}",
                p.name, MAX_NAME
            ));
        }
        if seen.contains(&p.name.as_str()) {
            return Err(format!("parameter `{}` is named twice", p.name));
        }
        seen.push(&p.name);
        if p.kind == Kind::Material && p.formula.is_some() {
            return Err(format!("parameter `{}`: a material takes no formula", p.name));
        }
        if p.formula.as_deref().map(too_long).unwrap_or(false) {
            return Err(format!("parameter `{}`: its formula is longer than {} characters", p.name, MAX_LEN));
        }
        if !fits(p.kind, &p.value) {
            return Err(format!("parameter `{}` holds {}, not {}", p.name, holds(p.kind), p.value.to_compact()));
        }
        if p.kind == Kind::Material {
            if let Value::Str(m) = &p.value {
                if !m.is_empty() && !has_material(m) {
                    return Err(format!("parameter `{}`: {}", p.name, no_material(m)));
                }
            }
        }
    }
    for (t, vals) in &fam.types {
        if t.trim().is_empty() || t.chars().count() > MAX_NAME {
            return Err(format!("type `{}`: a type needs a name, up to {} characters", t, MAX_NAME));
        }
        for (k, v) in vals.iter() {
            let p = match fam.param(k) {
                Some(p) => p,
                None => return Err(format!("type `{}`: `{}` isn't one of its parameters", t, k)),
            };
            if p.instance {
                return Err(format!("type `{}`: `{}` is an instance parameter; each component sets its own", t, k));
            }
            if p.formula.is_some() {
                return Err(format!("type `{}`: `{}` is worked out by its formula", t, k));
            }
            if !fits(p.kind, v) {
                return Err(format!("parameter `{}` holds {}, not {}", k, holds(p.kind), v.to_compact()));
            }
            if p.kind == Kind::Material {
                if let Value::Str(m) = v {
                    if !m.is_empty() && !has_material(m) {
                        return Err(format!("type `{}`: {}", t, no_material(m)));
                    }
                }
            }
        }
    }
    let mats = fam.material_params();
    for (i, f) in fam.forms.iter().enumerate() {
        let n = i + 1;
        let shapes = (!f.profile.is_empty()) as u8 + f.circle.is_some() as u8 + (!f.mesh.is_empty()) as u8;
        if shapes != 1 {
            return Err(format!("form {}: it takes a `profile`, a `circle` or a `mesh`, one of them", n));
        }
        if !f.mesh.is_empty() && f.axis.is_some() {
            return Err(format!("form {}: a `mesh` is as it is; an `axis` turns a `profile` or a `circle`", n));
        }
        if !f.material.is_empty() && !mats.contains(&f.material) && !has_material(&f.material) {
            return Err(format!("form {}: {}", n, no_material(&f.material)));
        }
        if form_formulas(f).into_iter().any(too_long) {
            return Err(format!("form {}: a formula of it is longer than {} characters", n, MAX_LEN));
        }
    }
    for (i, s) in fam.symbols.iter().enumerate() {
        if let Some(t) = &s.text {
            match text_refs(&t.value) {
                Err(()) => return Err(format!("symbol {}: its text has a `{{` with no `}}` to close it", i + 1)),
                Ok(refs) => {
                    for r in refs {
                        if fam.param(r.trim()).is_none() {
                            return Err(format!(
                                "symbol {}: its text reads `{{{}}}`, which isn't one of the family's parameters",
                                i + 1,
                                r
                            ));
                        }
                    }
                }
            }
        }
    }
    if fam.symbols.iter().any(|s| symbol_formulas(s).into_iter().any(too_long)) {
        return Err(format!("a formula of a symbol is longer than {} characters", MAX_LEN));
    }
    if fam.connectors.iter().filter(|c| c.kind == ConnKind::Power).count() > 1 {
        return Err("it has two power connectors: keep one, a device draws its load through one".into());
    }
    for (i, c) in fam.connectors.iter().enumerate() {
        let n = i + 1;
        if connector_formulas(c).into_iter().any(too_long) {
            return Err(format!("connector {}: a formula of it is longer than {} characters", n, MAX_LEN));
        }
        match (c.kind, c.system) {
            (ConnKind::Power, System::Switch) => {
                return Err(format!(
                    "connector {}: a power connector's system is `power-balanced` or `power-unbalanced`, not `switch`",
                    n
                ))
            }
            (ConnKind::Switch, System::Balanced | System::Unbalanced) => {
                return Err(format!("connector {}: a switch connector's system is `switch`", n))
            }
            _ => {}
        }
        if !(1..=3).contains(&c.poles) {
            return Err(format!("connector {}: poles are 1, 2 or 3, not {}", n, c.poles));
        }
        if let Load::PerPole(v) = &c.load_va {
            if c.system != System::Unbalanced || v.len() != c.poles as usize {
                return Err(format!(
                    "connector {}: a load per phase is a list of one for each pole ({}) on a `power-unbalanced` connector; a balanced one takes a single load",
                    n, c.poles
                ));
            }
        }
    }
    for (t, _) in &fam.types {
        let ev = Eval::new(fam, Some(t), None, None);
        worked_out(fam, &ev).map_err(|e| format!("type `{}`: {}", t, e))?;
    }
    Ok(())
}

/// The family worked out for one type (or one component): its parameters' formulas, its
/// connectors, its symbols and its forms; the first refusal.
pub fn worked_out(fam: &Family, ev: &Eval) -> Result<(), String> {
    for p in &fam.parameters {
        if p.formula.is_some() && p.kind != Kind::Material {
            ev.param(p)?;
        }
    }
    for (i, c) in fam.connectors.iter().enumerate() {
        connector_values(c, ev).map_err(|e| format!("connector {}: {}", i + 1, e))?;
    }
    for (i, s) in fam.symbols.iter().enumerate() {
        check_symbol(fam, s, ev).map_err(|e| format!("symbol {}: {}", i + 1, e))?;
    }
    for (i, f) in fam.forms.iter().enumerate() {
        build_form(f, ev).map_err(|e| format!("form {}: {}", i + 1, e))?;
    }
    Ok(())
}

// ---------------------------------------------------------------- connectors worked out

/// A connector worked out: its voltage, power factor and load on each pole (none on a switch).
#[derive(Clone, Debug, PartialEq)]
pub struct ConnectorValues {
    pub voltage: f64,
    pub power_factor: f64,
    pub load_by_phase: Vec<f64>,
}

impl ConnectorValues {
    /// Its load in all (the sum of its phases').
    pub fn load(&self) -> f64 {
        self.load_by_phase.iter().copied().sum::<f64>()
    }
}

fn part_usable(ev: &Eval, e: &Expr, what: &str) -> Result<f64, String> {
    ev.usable(e).map_err(|m| format!("its {}: {}", what, m))
}

/// A connector worked out, refused where its values are out of their range.
pub fn connector_values(c: &Connector, ev: &Eval) -> Result<ConnectorValues, String> {
    let voltage = part_usable(ev, &c.voltage, "voltage")?;
    if c.kind == ConnKind::Power && !(voltage > 0.0 && voltage <= 100_000.0) {
        return Err(format!("its voltage is {} V; it takes more than 0 and up to 100000", disp(voltage)));
    }
    let power_factor = part_usable(ev, &c.power_factor, "power factor")?;
    if c.kind == ConnKind::Power && !(power_factor > 0.0 && power_factor <= 1.0) {
        return Err(format!("its power factor is {}; it takes more than 0 and up to 1", disp(power_factor)));
    }
    let loads: Vec<f64> = match &c.load_va {
        Load::One(e) => vec![part_usable(ev, e, "load")?],
        Load::PerPole(v) => {
            let mut out = Vec::with_capacity(v.len());
            for e in v {
                out.push(part_usable(ev, e, "load")?);
            }
            out
        }
    };
    if c.kind == ConnKind::Switch {
        if loads.iter().any(|l| *l != 0.0) {
            return Err("a switch carries no load; leave `load_va` out".into());
        }
        return Ok(ConnectorValues { voltage, power_factor, load_by_phase: Vec::new() });
    }
    for l in &loads {
        if !(*l >= 0.0 && *l <= MAX_COORD) {
            return Err(format!("its load is {} VA; it takes 0 up to 1000000000", disp(*l)));
        }
    }
    let poles = c.poles.max(1) as usize;
    let load_by_phase = match &c.load_va {
        Load::PerPole(_) => loads,
        Load::One(_) => vec![loads[0] / poles as f64; poles],
    };
    Ok(ConnectorValues { voltage, power_factor, load_by_phase })
}

// ---------------------------------------------------------------- symbols worked out

/// A symbol's text with its `{Parameter}`s said.
pub fn said_text(fam: &Family, value: &str, ev: &Eval) -> Result<String, String> {
    let mut out = String::new();
    let mut rest = value;
    while let Some(i) = rest.find('{') {
        out.push_str(&rest[..i]);
        let after = &rest[i + 1..];
        let j = after.find('}').unwrap_or(after.len());
        let name = after[..j].trim();
        if let Some(p) = fam.param(name) {
            match ev.param(p)? {
                super::eval::PVal::Num(x) => out.push_str(&said_number(x)),
                super::eval::PVal::Mat(m) => out.push_str(&m),
            }
        }
        rest = if j < after.len() { &after[j + 1..] } else { "" };
    }
    out.push_str(rest);
    Ok(out)
}

fn check_symbol(fam: &Family, s: &Symbol, ev: &Eval) -> Result<(), String> {
    let shapes = (!s.line.is_empty()) as u8 + s.arc.is_some() as u8 + s.text.is_some() as u8 + s.dot.is_some() as u8;
    if shapes != 1 || s.line.len() > MAX_LINE {
        return Err(format!(
            "it takes a `line` of up to {} points, an `arc`, a `text` or a `dot`, one of them",
            MAX_LINE
        ));
    }
    if !ev.visible(&s.visible)? {
        return Ok(());
    }
    for p in &s.line {
        ev.point(p)?;
    }
    if let Some(a) = &s.arc {
        ev.point(&a.centre)?;
        let r = ev.usable(&a.radius)?;
        let from = ev.usable(&a.from)?;
        let to = ev.usable(&a.to)?;
        let span = (to - from).abs();
        if !(r > 0.0 && span > 0.0 && span <= 360.0) {
            return Err(format!(
                "its arc has radius {} and runs from {} to {} degrees; it needs a radius above zero and up to a full turn",
                disp(r),
                disp(from),
                disp(to)
            ));
        }
    }
    if let Some(t) = &s.text {
        ev.point(&t.at)?;
        let h = ev.usable(&t.height)?;
        if !(h > 0.0) {
            return Err(format!("its text has height {}; it needs a height above zero", disp(h)));
        }
        let said = said_text(fam, &t.value, ev)?;
        if said.trim().is_empty() {
            return Err("its text is empty; give it a `value` with something to letter".into());
        }
        if said.chars().count() > MAX_TEXT {
            return Err(format!("its text is longer than {} characters", MAX_TEXT));
        }
    }
    if let Some(d) = &s.dot {
        ev.point(&d.centre)?;
        let r = ev.usable(&d.radius)?;
        if !(r > 0.0) {
            return Err(format!("its dot has radius {}; it needs a radius above zero", disp(r)));
        }
    }
    Ok(())
}

// ---------------------------------------------------------------- forms worked out

/// A form worked out: where it is (none when it isn't there), a solid or a void, of what.
#[derive(Clone, Debug)]
pub struct Piece {
    /// Its place among the family's forms, from 0.
    pub index: usize,
    pub void: bool,
    /// Its material's name ("" for none): a material parameter's value where it names one.
    pub material: String,
    pub solid: Solid,
    pub bbox: Option<Bbox>,
}

/// Which side of an axis a point is on: +1, -1, or 0 on it (within a millionth).
fn side(d: f64) -> i8 {
    if d >= 1e-6 {
        1
    } else if d <= -1e-6 {
        -1
    } else {
        0
    }
}

/// A form worked out for the values `ev` gives: None where it isn't visible.
pub fn build_form(f: &Form, ev: &Eval) -> Result<Option<Solid>, String> {
    if !ev.visible(&f.visible)? {
        return Ok(None);
    }
    if f.profile.len() > MAX_PROFILE {
        return Err(format!("its profile has more than {} corners", MAX_PROFILE));
    }
    if !f.mesh.is_empty() {
        for t in &f.mesh {
            for p in t {
                for c in p {
                    if !(c.is_finite() && c.abs() <= MAX_COORD) {
                        return Err("a corner of it isn't a usable number".into());
                    }
                }
            }
        }
        return Ok(Some(geom::mesh(&f.mesh)));
    }
    let mut circle: Option<([f64; 2], f64)> = None;
    let pts: Vec<[f64; 2]> = if let Some(c) = &f.circle {
        let centre = ev.point(&c.centre)?;
        let r = ev.usable(&c.radius)?;
        if !(r > 0.0) {
            return Err(format!("its circle's radius is {}; it needs one above zero", disp(r)));
        }
        circle = Some((centre, r));
        geom::circle(centre, r)
    } else {
        let mut v = Vec::with_capacity(f.profile.len());
        for p in &f.profile {
            v.push(ev.point(p)?);
        }
        v
    };
    let from = ev.usable(&f.from)?;
    let to = ev.usable(&f.to)?;
    let axis = match &f.axis {
        Some(a) => Some([ev.point(&a[0])?, ev.point(&a[1])?]),
        None => None,
    };
    if geom::area(&pts).abs() < 1.0 {
        return Err("its profile has no area: it needs three corners or more, or a circle".into());
    }
    match axis {
        Some(ax) => {
            if from >= to {
                return Err(format!("sweeps nothing: from {} to {} degrees", disp(from), disp(to)));
            }
            if to - from > 360.0 {
                return Err(format!(
                    "turns more than all the way round: from {} to {} degrees, 360 at most",
                    disp(from),
                    disp(to)
                ));
            }
            let d = [ax[1][0] - ax[0][0], ax[1][1] - ax[0][1]];
            let l = (d[0] * d[0] + d[1] * d[1]).sqrt();
            if l < 1e-6 {
                return Err("its axis starts and ends at one point: it needs a direction".into());
            }
            let u = [d[0] / l, d[1] / l];
            let dist = |p: [f64; 2]| u[0] * (p[1] - ax[0][1]) - u[1] * (p[0] - ax[0][0]);
            let crosses = match circle {
                Some((c, r)) => r - dist(c).abs() >= 1e-6,
                None => {
                    let sides: Vec<i8> = pts.iter().map(|p| side(dist(*p))).collect();
                    sides.contains(&1) && sides.contains(&-1)
                }
            };
            if crosses {
                return Err("its profile crosses its axis: draw it to one side of it".into());
            }
            Ok(Some(geom::revolve(f.plane, &pts, ax, from, to)))
        }
        None => {
            if from >= to {
                return Err(format!("sweeps nothing: from {} to {}", disp(from), disp(to)));
            }
            Ok(Some(geom::extrude(f.plane, &pts, from, to)))
        }
    }
}

/// The material a form is of for these values: a material parameter's value where it names one.
pub fn form_material(fam: &Family, f: &Form, ev: &Eval) -> String {
    if f.material.is_empty() {
        return String::new();
    }
    match fam.param(&f.material) {
        Some(p) if p.kind == Kind::Material => match ev.param(p) {
            Ok(super::eval::PVal::Mat(m)) => m,
            _ => String::new(),
        },
        _ => f.material.clone(),
    }
}

/// Each form worked out that builds (and is there), before any void cuts it.
pub fn pieces(fam: &Family, ev: &Eval) -> Vec<Piece> {
    let mut out = Vec::new();
    for (i, f) in fam.forms.iter().enumerate() {
        if let Ok(Some(solid)) = build_form(f, ev) {
            let bbox = solid.bbox();
            out.push(Piece { index: i, void: f.void, material: form_material(fam, f, ev), solid, bbox });
        }
    }
    out
}

/// The solid forms with the voids cut out of those listed before them.
pub fn cut(pieces: &[Piece]) -> Vec<Piece> {
    let mut out: Vec<Piece> = Vec::new();
    for p in pieces {
        if !p.void {
            out.push(p.clone());
            continue;
        }
        let Some(vb) = p.bbox else { continue };
        for q in out.iter_mut() {
            let Some(qb) = q.bbox else { continue };
            if !qb.overlaps(&vb) {
                continue;
            }
            if let Some(s) = geom::subtract(&q.solid, &p.solid) {
                q.solid = s;
            }
        }
    }
    out
}

/// How high the forms reach over the base, after voids cut them (0 at least).
pub fn height(pieces: &[Piece]) -> f64 {
    let mut h: f64 = 0.0;
    for p in cut(pieces) {
        for poly in &p.solid.polys {
            for v in poly {
                h = h.max(v[2]);
            }
        }
    }
    h
}

/// A length as the warnings say it: to a tenth of a millimetre.
fn tenth(x: f64) -> String {
    disp((x * 10.0).round() / 10.0)
}

/// The warnings the family gives, each said once with the types it holds in.
pub fn warnings(fam: &Family) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    if fam.hosted() && fam.symbols.is_empty() {
        out.push(
            "its plan draws no symbols: a door's or a window's plan shows its swing or its sill, and this one shows nothing"
                .into(),
        );
    }
    let mut per: Vec<(String, Vec<String>)> = Vec::new();
    for (t, _) in &fam.types {
        let ev = Eval::new(fam, Some(t), None, None);
        let ps = pieces(fam, &ev);
        let opening = if fam.hosted() {
            let w = ev.value_of("Width").and_then(|r| r.ok()).map(|v| v.num()).unwrap_or(0.0);
            let h = ev.value_of("Height").and_then(|r| r.ok()).map(|v| v.num()).unwrap_or(0.0);
            Some((w, h, ev.wall.unwrap_or(super::eval::DEFAULT_WALL)))
        } else {
            None
        };
        for (k, p) in ps.iter().enumerate() {
            let n = p.index + 1;
            let Some(b) = p.bbox else { continue };
            let mut ws: Vec<String> = Vec::new();
            if p.void {
                let hits = ps[..k].iter().any(|q| !q.void && q.bbox.map(|qb| qb.overlaps(&b)).unwrap_or(false));
                if !hits {
                    ws.push(format!("form {}: its void passes through no solid form listed before it; it cuts nothing", n));
                }
            } else if let Some((w, h, wall)) = opening {
                let thick = b.max[1] - b.min[1];
                if thick > wall {
                    ws.push(format!(
                        "form {}: it is {} mm thick across the wall where the wall is {} mm",
                        n,
                        tenth(thick),
                        tenth(wall)
                    ));
                }
                let outside = b.max[0] < -w / 2.0 || b.min[0] > w / 2.0 || b.max[2] < 0.0 || b.min[2] > h;
                if outside {
                    ws.push(format!(
                        "form {}: it lies wholly outside the opening (x {}…{} mm, z {}…{} mm)",
                        n,
                        tenth(b.min[0]),
                        tenth(b.max[0]),
                        tenth(b.min[2]),
                        tenth(b.max[2])
                    ));
                }
            }
            for w in ws {
                match per.iter_mut().find(|(m, _)| *m == w) {
                    Some((_, ts)) => ts.push(t.clone()),
                    None => per.push((w, vec![t.clone()])),
                }
            }
        }
    }
    for (w, ts) in per {
        let list: Vec<String> = ts.iter().map(|t| format!("`{}`", t)).collect();
        out.push(format!("{} (in type {})", w, list.join(", ")));
    }
    out
}

/// What the original finds wrong with a family: (errors, warnings). The errors are each formula
/// that doesn't read, then the first refusal of its rules, each after `family `name`: `.
pub fn problems(fam: &Family, name: &str, has_material: &dyn Fn(&str) -> bool) -> (Vec<String>, Vec<String>) {
    let mut errors: Vec<String> = read_formulas(fam).into_iter().map(|e| format!("family `{}`: {}", name, e)).collect();
    if let Err(e) = rules(fam, has_material) {
        errors.push(format!("family `{}`: {}", name, e));
    }
    (errors, warnings(fam))
}

/// A refusal carrying every error and warning found.
pub fn refusal(name: &str, errors: &[String], warnings: &[String]) -> String {
    let mut lines: Vec<String> = errors.to_vec();
    for w in warnings {
        lines.push(format!("family `{}`: warning: {}", name, w));
    }
    lines.join("\n")
}

//! A family's library entries (`family`, `family-type` "Family: Type", `family-parameter`
//! "Family: Parameter") and its parts' ids and GUIDs, given as the original gives them after a
//! command: the entries first (the family's, its types' in name order, its parameters' in their
//! order), then the parts that need one (forms, symbols, connectors), ids counting down from the
//! lowest the library and the parts use (or, where that would run into the elements', the next
//! element id; for parts, up from the highest).

use crate::json::{Map, Value};
use crate::project::Project;
use std::collections::HashSet;

pub const FAMILY: &str = "family";
pub const FAMILY_TYPE: &str = "family-type";
pub const FAMILY_PARAMETER: &str = "family-parameter";

/// The library name of a family's type or parameter.
pub fn entry_name(family: &str, part: &str) -> String {
    format!("{}: {}", family, part)
}

fn scan_ids(v: &Value, f: &mut dyn FnMut(u64)) {
    match v {
        Value::Obj(m) => {
            if let Some(id) = m.get("id").and_then(|x| x.as_u64()) {
                if id != 0 {
                    f(id);
                }
            }
            m.items.iter().for_each(|(_, x)| scan_ids(x, f));
        }
        Value::Arr(a) => a.iter().for_each(|x| scan_ids(x, f)),
        _ => {}
    }
}

/// Every part id the project's sections hold (types' layers, families' parts…).
fn part_ids(pr: &Project, f: &mut dyn FnMut(u64)) {
    for (k, v) in &pr.doc.items {
        if k != "elements" && k != "library" {
            scan_ids(v, f);
        }
    }
}

/// The lowest id the library and the parts use, and the lowest handed out.
fn lowest(pr: &Project) -> u64 {
    let mut low = pr.lib_low.min(1_000_000);
    if let Some(k) = pr.library.keys().next() {
        low = low.min(*k);
    }
    part_ids(pr, &mut |id| low = low.min(id));
    low
}

/// The highest id the library and the parts use.
fn highest(pr: &Project) -> u64 {
    let mut high = pr.library.keys().next_back().copied().unwrap_or(0);
    part_ids(pr, &mut |id| {
        if id >= 900_000 {
            high = high.max(id)
        }
    });
    high
}

/// A new library entry's id.
pub fn alloc_entry(pr: &mut Project) -> u64 {
    let low = lowest(pr);
    let next = pr.next_id();
    if low > next {
        pr.lib_low = low - 1;
        low - 1
    } else {
        pr.doc.insert("next_id", Value::u(next + 1));
        next
    }
}

/// A new part's id.
pub fn alloc_part(pr: &mut Project) -> u64 {
    let low = lowest(pr);
    if low > pr.next_id() {
        pr.lib_low = low - 1;
        low - 1
    } else {
        highest(pr) + 1
    }
}

/// Adds a library entry of a kind and name where there's none: its id.
pub fn ensure_entry(pr: &mut Project, kind: &str, name: &str) -> u64 {
    if let Some(id) = pr.lib_find(kind, name) {
        return id;
    }
    let id = alloc_entry(pr);
    let g = crate::structure::common::new_guid();
    pr.library.insert(id, crate::jobj! {"kind" => kind, "name" => name, "guid" => g});
    id
}

/// Takes a library entry away.
pub fn remove_entry(pr: &mut Project, kind: &str, name: &str) {
    if let Some(id) = pr.lib_find(kind, name) {
        pr.library.remove(&id);
    }
}

/// Renames a library entry (it keeps its id and GUID).
pub fn rename_entry(pr: &mut Project, kind: &str, from: &str, to: &str) {
    if let Some(id) = pr.lib_find(kind, from) {
        if let Some(e) = pr.library.get_mut(&id) {
            e.set("name", Value::s(to));
        }
    }
}

/// The ids and GUIDs the project uses but those of one family's parts.
fn used_but(pr: &Project, family: &str) -> (HashSet<u64>, HashSet<String>) {
    let mut ids: HashSet<u64> = pr.elements.keys().copied().collect();
    let mut guids: HashSet<String> = HashSet::new();
    for e in pr.elements.values() {
        if let Some(g) = e.get("guid").and_then(|g| g.as_str()) {
            guids.insert(g.to_string());
        }
    }
    for (id, e) in &pr.library {
        ids.insert(*id);
        if let Some(g) = e.get("guid").and_then(|g| g.as_str()) {
            guids.insert(g.to_string());
        }
    }
    fn scan(v: &Value, ids: &mut HashSet<u64>, guids: &mut HashSet<String>) {
        match v {
            Value::Obj(m) => {
                if let Some(id) = m.get("id").and_then(|x| x.as_u64()) {
                    ids.insert(id);
                }
                if m.get("id").is_some() {
                    if let Some(g) = m.get("guid").and_then(|g| g.as_str()) {
                        guids.insert(g.to_string());
                    }
                }
                m.items.iter().for_each(|(_, x)| scan(x, ids, guids));
            }
            Value::Arr(a) => a.iter().for_each(|x| scan(x, ids, guids)),
            _ => {}
        }
    }
    for (k, v) in &pr.doc.items {
        if k == "elements" || k == "library" {
            continue;
        }
        if k == "families" {
            if let Value::Obj(fams) = v {
                for (n, f) in &fams.items {
                    if n != family {
                        scan(f, &mut ids, &mut guids);
                    }
                }
            }
            continue;
        }
        scan(v, &mut ids, &mut guids);
    }
    (ids, guids)
}

/// Gives a family's parts (in the file) that need one an id and a GUID: one it hasn't, or one
/// something else in the project (or a part of it before) has. Forms, then symbols, then
/// connectors.
pub fn fix_parts(pr: &mut Project, family: &str) {
    let (mut ids, mut guids) = used_but(pr, family);
    let mut need_id: Vec<(&'static str, usize)> = Vec::new();
    let mut new_guid: Vec<(&'static str, usize, String)> = Vec::new();
    {
        let Some(f) = pr.section("families").and_then(|m| m.get(family)) else { return };
        for key in ["forms", "symbols", "connectors"] {
            let Some(list) = f.get(key).and_then(|x| x.as_arr()) else { continue };
            for (i, part) in list.iter().enumerate() {
                match part.get("id").and_then(|x| x.as_u64()).filter(|n| *n != 0) {
                    Some(id) if !ids.contains(&id) => {
                        ids.insert(id);
                    }
                    _ => need_id.push((key, i)),
                }
                match part.get("guid").and_then(|g| g.as_str()) {
                    Some(g) if !guids.contains(g) => {
                        guids.insert(g.to_string());
                    }
                    _ => {
                        let g = crate::structure::common::new_guid();
                        guids.insert(g.clone());
                        new_guid.push((key, i, g));
                    }
                }
            }
        }
    }
    let mut fresh: Vec<u64> = Vec::with_capacity(need_id.len());
    for _ in &need_id {
        let id = alloc_part(pr);
        fresh.push(id);
        // what's handed out counts as used for the next
        set_part(pr, family, need_id[fresh.len() - 1], |m| m.insert_first("id", Value::u(id)));
    }
    for (key, i, g) in new_guid {
        set_part(pr, family, (key, i), |m| m.insert_after_id("guid", Value::s(&g)));
    }
}

trait PartMap {
    fn insert_first(&mut self, k: &str, v: Value);
    fn insert_after_id(&mut self, k: &str, v: Value);
}

impl PartMap for Map {
    fn insert_first(&mut self, k: &str, v: Value) {
        if let Some(slot) = self.get_mut(k) {
            *slot = v;
        } else {
            self.items.insert(0, (k.to_string(), v));
        }
    }
    fn insert_after_id(&mut self, k: &str, v: Value) {
        if let Some(slot) = self.get_mut(k) {
            *slot = v;
        } else {
            let at = if self.contains("id") { 1 } else { 0 };
            self.items.insert(at, (k.to_string(), v));
        }
    }
}

fn set_part(pr: &mut Project, family: &str, at: (&str, usize), f: impl FnOnce(&mut Map)) {
    let Some(fam) = pr.section_mut("families").get_mut(family) else { return };
    let Some(list) = fam.get_mut(at.0).and_then(|x| x.as_arr_mut()) else { return };
    if let Some(Value::Obj(m)) = list.get_mut(at.1) {
        f(m);
    }
}

//! The `family` command: list, read, create, change (parts patched, deleted, replaced by
//! place), dry run, rename, delete, load from a file and save to one.

use super::check::{problems, refusal};
use super::de::{self, DeR};
use super::eval::{values_view, Eval};
use super::ids;
use super::model::*;
use super::{exists, family_of, has_material, put_family, view_of};
use crate::commands::params::{opt_bool, opt_text};
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use crate::structure::common::R;

const CMD: &str = "family";

/// The keys that change a family.
const CHANGE_KEYS: &[&str] = &[
    "category",
    "parameters",
    "types",
    "forms",
    "symbols",
    "connectors",
    "form",
    "symbol",
    "delete_form",
    "delete_symbol",
    "operation",
    "kind",
    "rename",
];

/// The keys a family file gives.
const FILE_KEYS: &[&str] = &["category", "parameters", "types", "forms", "symbols", "connectors", "operation", "kind"];

fn given(p: &Value, k: &str) -> Option<Value> {
    match p.get(k) {
        None | Some(Value::Null) => None,
        Some(v) => Some(v.clone()),
    }
}

/// What a command asks of a family's definition, read in the original's order.
#[derive(Default)]
struct Change {
    category: Option<String>,
    parameters: Option<Vec<Param>>,
    forms: Option<Vec<Form>>,
    symbols: Option<Vec<Symbol>>,
    form: Option<Map>,
    symbol: Option<Map>,
    connectors: Option<Vec<Connector>>,
    operation: Option<String>,
    kind: Option<String>,
    types: Option<Vec<(String, Option<Map>)>>,
    rename: Option<String>,
    delete_form: Option<Value>,
    delete_symbol: Option<Value>,
}

fn serde<T>(key: &str, r: DeR<T>) -> R<T> {
    r.map_err(|e| format!("{}: `{}`: {}", CMD, key, e))
}

fn patch_of(src: &Value, key: &str, what: &str) -> R<Option<Map>> {
    match given(src, key) {
        None => Ok(None),
        Some(Value::Obj(m)) => Ok(Some(m)),
        Some(v) => Err(format!("{}: `{}` must be {{id | guid, …the {}'s fields}}, not {}", CMD, key, what, v.to_compact())),
    }
}

/// Reads the change from `src` (the command's parameters, or a family file's object).
fn read_change(src: &Value, from_file: bool) -> R<Change> {
    let mut c = Change::default();
    if let Some(v) = given(src, "category") {
        c.category = Some(serde("category", de::de_category(&v))?);
    }
    if let Some(v) = given(src, "parameters") {
        c.parameters = Some(serde("parameters", de::de_seq(&v, &de::de_param))?);
    }
    if let Some(v) = given(src, "forms") {
        c.forms = Some(serde("forms", de::de_seq(&v, &de::de_form))?);
    }
    if let Some(v) = given(src, "symbols") {
        c.symbols = Some(serde("symbols", de::de_seq(&v, &de::de_symbol))?);
    }
    if !from_file {
        c.form = patch_of(src, "form", "form")?;
        c.symbol = patch_of(src, "symbol", "symbol")?;
    }
    if let Some(v) = given(src, "connectors") {
        c.connectors = Some(serde("connectors", de::de_seq(&v, &de::de_connector))?);
    }
    c.operation = opt_text(src, CMD, "operation")?;
    c.kind = opt_text(src, CMD, "kind")?;
    if let Some(v) = given(src, "types") {
        c.types = Some(serde("types", de::de_types(&v))?);
    }
    if !from_file {
        c.rename = opt_text(src, CMD, "rename")?;
        c.delete_form = given(src, "delete_form");
        c.delete_symbol = given(src, "delete_symbol");
    }
    Ok(c)
}

/// What a dry run reports.
#[derive(Default)]
struct Report {
    forms_deleted: Vec<u64>,
    forms_patched: Vec<u64>,
    forms_replaced: usize,
    symbols_deleted: Vec<u64>,
    symbols_patched: Vec<u64>,
    symbols_replaced: usize,
}

/// A part chosen by `id` (a number, or one in a string) or `guid`.
enum Pick {
    Id(u64),
    Guid(String),
}

impl Pick {
    fn shown(&self) -> String {
        match self {
            Pick::Id(n) => n.to_string(),
            Pick::Guid(g) => g.clone(),
        }
    }
}

fn pick_of(v: &Value) -> Option<Pick> {
    match v {
        Value::Num(n) => {
            let x = n.as_f64();
            if x >= 0.0 && x.fract() == 0.0 {
                Some(Pick::Id(x as u64))
            } else {
                None
            }
        }
        Value::Str(s) => {
            let t = s.trim();
            if !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit()) {
                return t.parse::<u64>().ok().map(Pick::Id);
            }
            de::real_guid(s).map(Pick::Guid)
        }
        _ => None,
    }
}

fn matches(pick: &Pick, id: Option<u64>, guid: &Option<GRef>) -> bool {
    match pick {
        Pick::Id(n) => id == Some(*n),
        Pick::Guid(g) => guid.as_ref().and_then(|x| x.guid()) == Some(g.as_str()),
    }
}

/// Binds new parts to the old ones by place: one given without an id or a GUID takes those of
/// the part in its place before.
fn keep_by_place<T>(new: &mut [T], old: &[T], get: impl Fn(&T) -> (Option<u64>, Option<GRef>), set: impl Fn(&mut T, Option<u64>, Option<GRef>)) {
    for (i, n) in new.iter_mut().enumerate() {
        let (id, g) = get(n);
        if id.is_none() && g.is_none() {
            if let Some(o) = old.get(i) {
                let (oid, og) = get(o);
                set(n, oid, og);
            }
        }
    }
}

fn not_of(what: &str, pick: &Pick, family: &str) -> String {
    format!("{}: {} {} is not of family {:?}", CMD, what, pick.shown(), family)
}

/// The `id` or `guid` a patch picks its part by.
fn patch_pick(m: &Map, what: &str) -> R<Pick> {
    let sel = m.get("id").filter(|v| !v.is_null()).or_else(|| m.get("guid").filter(|v| !v.is_null()));
    match sel {
        None => Err(format!("{}: `{}` needs the {}'s `id` or `guid`", CMD, what, what)),
        Some(v) => pick_of(v).ok_or_else(|| format!("{}: `{}` needs the {}'s `id` or `guid`, not {}", CMD, what, what, v.to_compact())),
    }
}

/// Merges a patch's fields over a part's (a null taking one away).
fn merged(part: Value, patch: &Map) -> Value {
    let mut m = match part {
        Value::Obj(m) => m,
        _ => Map::new(),
    };
    for (k, v) in patch.iter() {
        if k == "id" || k == "guid" {
            continue;
        }
        if v.is_null() {
            m.remove(k);
        } else {
            m.insert(k, v.clone());
        }
    }
    Value::Obj(m)
}

fn form_view(f: &Form, fam: &Family) -> Value {
    let mut one = fam.clone();
    one.forms = vec![f.clone()];
    one.view().get("forms").and_then(|a| a.as_arr()).and_then(|a| a.first()).cloned().unwrap_or(Value::Null)
}

/// Builds the family a change makes of `old` (none: a new one).
fn apply(old: Option<&Family>, name: &str, c: &Change, rep: &mut Report) -> R<(Family, String)> {
    let mut f = old.cloned().unwrap_or_default();
    let mut name = name.to_string();
    if let Some(cat) = &c.category {
        f.category = cat.clone();
    }
    if let Some(ps) = &c.parameters {
        f.parameters = ps.clone();
    }
    if let Some(fs) = &c.forms {
        let mut fs = fs.clone();
        keep_by_place(&mut fs, &f.forms, |x| (x.id, x.guid.clone()), |x, id, g| {
            x.id = id;
            x.guid = g;
        });
        rep.forms_replaced = fs.len();
        f.forms = fs;
    }
    if let Some(ss) = &c.symbols {
        let mut ss = ss.clone();
        keep_by_place(&mut ss, &f.symbols, |x| (x.id, x.guid.clone()), |x, id, g| {
            x.id = id;
            x.guid = g;
        });
        rep.symbols_replaced = ss.len();
        f.symbols = ss;
    }
    if let Some(patch) = &c.form {
        let pick = patch_pick(patch, "form")?;
        let i = f.forms.iter().position(|x| matches(&pick, x.id, &x.guid)).ok_or_else(|| not_of("form", &pick, &name))?;
        let v = merged(form_view(&f.forms[i], &f), patch);
        let mut nf = de::de_form(&v).map_err(|e| format!("{}: form {} of family {:?}: {}", CMD, pick.shown(), name, e))?;
        nf.id = f.forms[i].id;
        nf.guid = f.forms[i].guid.clone();
        if let Some(id) = nf.id {
            rep.forms_patched.push(id);
        }
        f.forms[i] = nf;
    }
    if let Some(patch) = &c.symbol {
        let pick = patch_pick(patch, "symbol")?;
        let i = f.symbols.iter().position(|x| matches(&pick, x.id, &x.guid)).ok_or_else(|| not_of("symbol", &pick, &name))?;
        let v = merged(symbol_value(&f.symbols[i]), patch);
        let mut ns = de::de_symbol(&v).map_err(|e| format!("{}: symbol {} of family {:?}: {}", CMD, pick.shown(), name, e))?;
        ns.id = f.symbols[i].id;
        ns.guid = f.symbols[i].guid.clone();
        if let Some(id) = ns.id {
            rep.symbols_patched.push(id);
        }
        f.symbols[i] = ns;
    }
    if let Some(cs) = &c.connectors {
        let mut cs = cs.clone();
        keep_by_place(&mut cs, &f.connectors, |x| (x.id, x.guid.clone()), |x, id, g| {
            x.id = id;
            x.guid = g;
        });
        f.connectors = cs;
    }
    if let Some(o) = &c.operation {
        let t = o.trim().to_lowercase();
        if t.is_empty() {
            f.operation = None;
        } else if OPERATIONS.contains(&t.as_str()) {
            f.operation = Some(t);
        } else {
            return Err(format!("{}: `operation` is one of {}, not `{}`", CMD, OPERATIONS.join(", "), o));
        }
    }
    if let Some(k) = &c.kind {
        let t = k.trim();
        f.kind = if t.is_empty() { None } else { Some(t.to_string()) };
    }
    if let Some(ts) = &c.types {
        for (t, vals) in ts {
            match vals {
                None => f.remove_type(t),
                Some(vals) => {
                    let mut cur = f.type_values(t).cloned().unwrap_or_default();
                    for (k, v) in vals.iter() {
                        if v.is_null() {
                            cur.remove(k);
                        } else {
                            cur.insert_sorted(k, v.clone());
                        }
                    }
                    f.set_type(t, cur);
                }
            }
        }
    }
    if let Some(r) = &c.rename {
        let t = r.trim();
        if t.is_empty() {
            return Err(format!("{}: `rename` needs a name", CMD));
        }
        name = t.to_string();
    }
    for (key, what) in [("delete_form", "form"), ("delete_symbol", "symbol")] {
        let list = if key == "delete_form" { &c.delete_form } else { &c.delete_symbol };
        let Some(Value::Arr(a)) = list else { continue };
        for x in a {
            let pick = pick_of(x).ok_or_else(|| format!("{}: `{}` needs the {}'s `id` or `guid`, not {}", CMD, what, what, x.to_compact()))?;
            if what == "form" {
                let i = f.forms.iter().position(|y| matches(&pick, y.id, &y.guid)).ok_or_else(|| not_of(what, &pick, &name))?;
                if let Some(id) = f.forms[i].id {
                    rep.forms_deleted.push(id);
                }
                f.forms.remove(i);
            } else {
                let i = f.symbols.iter().position(|y| matches(&pick, y.id, &y.guid)).ok_or_else(|| not_of(what, &pick, &name))?;
                if let Some(id) = f.symbols[i].id {
                    rep.symbols_deleted.push(id);
                }
                f.symbols.remove(i);
            }
        }
    }
    Ok((f, name))
}

fn names(v: Vec<String>) -> Value {
    Value::Arr(v.into_iter().map(Value::Str).collect())
}

fn ids_value(v: &[u64]) -> Value {
    Value::Arr(v.iter().map(|x| Value::u(*x)).collect())
}

/// What a dry run says it would do.
fn changes(old: Option<&Family>, new: &Family, rep: &Report, rename: Option<&str>, deleted: bool) -> Value {
    let empty = Family::default();
    let o = old.unwrap_or(&empty);
    let (mut padd, mut pchg, mut prem) = (Vec::new(), Vec::new(), Vec::new());
    for p in &new.parameters {
        match o.param(&p.name) {
            None => padd.push(p.name.clone()),
            Some(op) => {
                if op != p {
                    pchg.push(p.name.clone())
                }
            }
        }
    }
    for p in &o.parameters {
        if new.param(&p.name).is_none() {
            prem.push(p.name.clone());
        }
    }
    let (mut tadd, mut tchg, mut trem) = (Vec::new(), Vec::new(), Vec::new());
    for (t, vals) in &new.types {
        match o.type_values(t) {
            None => tadd.push(t.clone()),
            Some(ov) => {
                if ov != vals {
                    tchg.push(t.clone())
                }
            }
        }
    }
    for (t, _) in &o.types {
        if new.type_values(t).is_none() {
            trem.push(t.clone());
        }
    }
    let part = |del: &[u64], pat: &[u64], rep: usize| crate::jobj! {"deleted" => ids_value(del), "patched" => ids_value(pat), "replaced" => rep};
    crate::jobj! {
        "deleted" => deleted,
        "forms" => part(&rep.forms_deleted, &rep.forms_patched, rep.forms_replaced),
        "parameters" => crate::jobj! {"added" => names(padd), "changed" => names(pchg), "removed" => names(prem)},
        "rename" => rename.map(Value::s).unwrap_or(Value::Null),
        "symbols" => part(&rep.symbols_deleted, &rep.symbols_patched, rep.symbols_replaced),
        "types" => crate::jobj! {"added" => names(tadd), "changed" => names(tchg), "removed" => names(trem)},
    }
}

fn all_values(fam: &Family) -> Value {
    let mut m = Map::new();
    for (t, _) in &fam.types {
        let ev = Eval::new(fam, Some(t), None, None);
        let v = ev.values().map(|vals| values_view(&vals)).unwrap_or_else(|_| Value::obj());
        m.insert_sorted(t, v);
    }
    Value::Obj(m)
}

fn warnings_value(w: &[String]) -> Value {
    Value::Arr(w.iter().map(|s| Value::s(s)).collect())
}

/// The family file at `path`: its object.
fn read_file(path: &str) -> R<Value> {
    let text = std::fs::read(path).map_err(|e| format!("{}: {}: {}", CMD, path, crate::commands::io_err(&e)))?;
    let v = crate::json::parse_bytes(&text).map_err(|e| format!("{}: {} is not a family: {}", CMD, path, e))?;
    if !matches!(v, Value::Obj(_)) {
        return Err(format!("{}: {} is not a family: it isn't an object", CMD, path));
    }
    Ok(v)
}

fn list(pr: &Project) -> Value {
    let mut out = Vec::new();
    if let Some(fams) = pr.section("families") {
        let mut names: Vec<&String> = fams.keys().collect();
        names.sort();
        for n in names {
            let f = fams.get(n).unwrap();
            let count = |k: &str| f.get(k).and_then(|x| x.as_arr()).map(|a| a.len()).unwrap_or(0);
            out.push(crate::jobj! {
                "category" => f.get("category").cloned().unwrap_or(Value::Null),
                "forms" => count("forms"),
                "name" => n.as_str(),
                "symbols" => count("symbols"),
                "types" => f.get("types").and_then(|t| t.as_obj()).map(|t| t.len()).unwrap_or(0),
            });
        }
    }
    crate::jobj! {"families" => Value::Arr(out)}
}

/// The elements (components, doors, windows) of a family, by id.
fn users(pr: &Project, name: &str) -> Vec<u64> {
    let Some(g) = pr.lib_guid(ids::FAMILY, name) else { return Vec::new() };
    pr.elements.iter().filter(|(_, e)| e.get("family").and_then(|f| f.as_str()) == Some(g.as_str())).map(|(id, _)| *id).collect()
}

pub fn run(s: &mut Session, p0: &Value) -> R<Value> {
    let p = crate::structure::types::names_for_guids(&s.project, p0);
    let path = opt_text(&p, CMD, "path")?;
    let file = match &path {
        Some(path) => Some(read_file(path)?),
        None => None,
    };
    let name = match (p.get("name").filter(|v| !v.is_null()), &file) {
        (Some(_), _) | (None, None) => opt_text(&p, CMD, "name")?,
        (None, Some(f)) => match f.get("name").filter(|v| !v.is_null()) {
            Some(_) => opt_text(f, CMD, "name")?,
            None => Some(
                std::path::Path::new(path.as_deref().unwrap_or(""))
                    .file_stem()
                    .map(|s| s.to_string_lossy().to_string())
                    .unwrap_or_default(),
            ),
        },
    };
    let name = name.map(|n| n.trim().to_string()).unwrap_or_default();
    let save = if file.is_none() { opt_text(&p, CMD, "save")? } else { None };
    let dry = opt_bool(&p, CMD, "dry_run")?.unwrap_or(false);
    let delete = if file.is_none() { opt_bool(&p, CMD, "delete")?.unwrap_or(false) } else { false };
    let change = match &file {
        Some(f) => read_change(f, true)?,
        None => read_change(&p, false)?,
    };
    let src = file.as_ref().unwrap_or(&p);
    let keys: &[&str] = if file.is_some() { FILE_KEYS } else { CHANGE_KEYS };
    let is_change = keys.iter().any(|k| given(src, k).is_some());

    if name.is_empty() {
        if save.is_some() {
            return Err(format!("{}: `name` is required: the family to save", CMD));
        }
        if delete || change.rename.is_some() {
            return Err(format!("{}: `name` is required: the family's", CMD));
        }
        return Ok(list(&s.project));
    }
    let pr = &s.project;
    if let Some(sp) = save {
        if !exists(pr, &name) {
            return Err(format!("{}: there's no family `{}` to save", CMD, name));
        }
        if dry {
            return Ok(crate::jobj! {"dry_run" => true, "name" => name.as_str(), "ok" => true, "path" => sp.as_str(), "saved" => false});
        }
        let mut v = view_of(pr, &name).unwrap_or_else(Value::obj);
        v.set("name", Value::s(&name));
        std::fs::write(&sp, v.sorted().to_pretty()).map_err(|e| format!("{}: {}: {}", CMD, sp, crate::commands::io_err(&e)))?;
        return Ok(crate::jobj! {"path" => sp.as_str(), "saved" => name.as_str()});
    }
    if delete {
        if !exists(pr, &name) {
            return Err(format!("{}: there's no family `{}`", CMD, name));
        }
        let us = users(pr, &name);
        if !us.is_empty() {
            let list: Vec<String> = us.iter().map(|x| x.to_string()).collect();
            return Err(format!("{}: elements {} are of `{}`; delete them first", CMD, list.join(", "), name));
        }
        if dry {
            let f = family_of(pr, &name).unwrap_or_default();
            let ch = changes(Some(&f), &f, &Report::default(), None, true);
            return Ok(crate::jobj! {"changes" => ch, "dry_run" => true, "name" => name.as_str(), "ok" => true, "warnings" => Value::Arr(Vec::new())});
        }
        super::remove_family(&mut s.project, &name);
        crate::structure::common::mark_step();
        return Ok(crate::jobj! {"deleted" => name.as_str(), "warnings" => Value::Arr(Vec::new())});
    }
    let old = family_of(pr, &name);
    if !is_change && !dry {
        let f = old.ok_or_else(|| format!("{}: there's no family `{}`", CMD, name))?;
        let w = super::check::warnings(&f);
        return Ok(crate::jobj! {"family" => f.view(), "name" => name.as_str(), "values" => all_values(&f), "warnings" => warnings_value(&w)});
    }
    let mut rep = Report::default();
    let (new, new_name) = apply(old.as_ref(), &name, &change, &mut rep)?;
    if new_name != name && exists(pr, &new_name) {
        return Err(format!("{}: there's a family `{}` already", CMD, new_name));
    }
    let (errors, warnings) = problems(&new, &new_name, &|m: &str| has_material(pr, m));
    if !errors.is_empty() {
        return Err(refusal(&new_name, &errors, &warnings));
    }
    crate::structure::component::check_family_users(pr, &name, &new)?;
    if dry {
        let ch = changes(old.as_ref(), &new, &rep, change.rename.as_deref().map(|r| r.trim()), false);
        return Ok(crate::jobj! {
            "changes" => ch,
            "dry_run" => true,
            "family" => new.view(),
            "name" => new_name.as_str(),
            "ok" => true,
            "values" => all_values(&new),
            "warnings" => warnings_value(&warnings),
        });
    }
    let reply = crate::jobj! {"family" => new.view(), "name" => new_name.as_str(), "warnings" => warnings_value(&warnings)};
    let pr = &mut s.project;
    if new_name != name {
        super::rename_family(pr, &name, &new_name);
    }
    put_family(pr, &new_name, &new);
    crate::structure::common::mark_step();
    Ok(reply)
}

//! `family`: the project's families, created, changed, read, listed, loaded and saved; their
//! model rules and what `inspect` warns of.
//!
//! A family (the file's `families`, by name in name order) is parameters, types that set them,
//! forms, plan symbols and connectors (`model`). The file holds materials by GUID, the original's
//! memory (and every reply) by name. Its library entries are `family`, `family-type`
//! ("Family: Type") and `family-parameter` ("Family: Parameter"), and its forms, symbols and
//! connectors are parts with an id and a GUID of their own (`ids`). The `family` command
//! (`cmd`) reads its parts as serde does (`de`), works every type out (`eval`, `geom`) and holds
//! the family to its rules (`check`).
//!
//! For other areas:
//! - [`family_of`] reads a project's family; [`type_values`] works a type out (a component's
//!   own values over it, a hosted one's wall), [`opening_size`] a door's or window's opening and
//!   sill; [`pieces_of`] the forms worked out as solids (voids cut), [`connectors_of`] what a
//!   device draws.
//! - [`put_family`] puts one into a project as a command leaves it (library entries, part ids):
//!   what loading a favorite does.
//! - [`inspect_view`] is `inspect`'s `families`; [`warnings`] what `inspect` warns of.

pub mod check;
mod cmd;
pub mod de;
pub mod eval;
pub mod geom;
pub mod ids;
pub mod model;

pub use check::{ConnectorValues, Piece};
pub use eval::{Eval, PVal};
pub use model::Family;

use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use crate::structure::common::R;

/// Runs the commands of this part.
pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "family" => cmd::run(s, p),
        _ => Err(format!("{}: not supported here", cid)),
    }
}

/// A material's name as a family names it: one the library has.
pub fn has_material(pr: &Project, name: &str) -> bool {
    pr.lib_find("material", name).is_some() || pr.section("materials").map(|m| m.contains(name)).unwrap_or(false)
}

/// The name of the material with this GUID (anything else as it is).
fn material_name(pr: &Project, s: &str) -> String {
    if let Some(id) = pr.lib_find_guid(s) {
        if let Some(e) = pr.library.get(&id) {
            if e.get("kind").and_then(|k| k.as_str()) == Some("material") {
                if let Some(n) = e.get("name").and_then(|n| n.as_str()) {
                    return n.to_string();
                }
            }
        }
    }
    s.to_string()
}

/// Whether the project has a family of this name.
pub fn exists(pr: &Project, name: &str) -> bool {
    pr.section("families").map(|f| f.contains(name)).unwrap_or(false)
}

/// A family of the project, as the original holds it (materials by name).
pub fn family_of(pr: &Project, name: &str) -> Option<Family> {
    let v = pr.section("families")?.get(name)?;
    Some(model::from_file(v, &|s: &str| material_name(pr, s)))
}

/// A family as `family` shows it.
pub fn view_of(pr: &Project, name: &str) -> Option<Value> {
    family_of(pr, name).map(|f| f.view())
}

/// The name of the family with this GUID (an element's `family`).
pub fn name_of_guid(pr: &Project, g: &str) -> Option<String> {
    let id = pr.lib_find_guid(g)?;
    let e = pr.library.get(&id)?;
    if e.get("kind").and_then(|k| k.as_str()) != Some(ids::FAMILY) {
        return None;
    }
    e.get("name").and_then(|n| n.as_str()).map(|s| s.to_string())
}

/// The family-type GUID of a family's type (what an element's `type` holds).
pub fn type_guid(pr: &Project, family: &str, ty: &str) -> Option<String> {
    pr.lib_guid(ids::FAMILY_TYPE, &ids::entry_name(family, ty))
}

/// The type name a family-type GUID names, for a family.
pub fn type_name_of_guid(pr: &Project, family: &str, g: &str) -> Option<String> {
    let id = pr.lib_find_guid(g)?;
    let e = pr.library.get(&id)?;
    if e.get("kind").and_then(|k| k.as_str()) != Some(ids::FAMILY_TYPE) {
        return None;
    }
    let n = e.get("name").and_then(|n| n.as_str())?;
    n.strip_prefix(&format!("{}: ", family)).map(|s| s.to_string())
}

/// The family-parameter GUID of a family's parameter (what an element's `params` keys it by).
pub fn param_guid(pr: &Project, family: &str, param: &str) -> Option<String> {
    pr.lib_guid(ids::FAMILY_PARAMETER, &ids::entry_name(family, param))
}

/// The parameter name a family-parameter GUID names, for a family.
pub fn param_name_of_guid(pr: &Project, family: &str, g: &str) -> Option<String> {
    let id = pr.lib_find_guid(g)?;
    let e = pr.library.get(&id)?;
    if e.get("kind").and_then(|k| k.as_str()) != Some(ids::FAMILY_PARAMETER) {
        return None;
    }
    let n = e.get("name").and_then(|n| n.as_str())?;
    n.strip_prefix(&format!("{}: ", family)).map(|s| s.to_string())
}

/// Remembers the lowest id the library and the parts hold, so that none is handed out again
/// once what has it goes (the original counts down from the lowest it has seen).
fn remember_lowest(pr: &mut Project) {
    let mut low = pr.lib_low;
    if let Some(k) = pr.library.keys().next() {
        low = low.min(*k);
    }
    fn scan(v: &Value, low: &mut u64) {
        match v {
            Value::Obj(m) => {
                if let Some(id) = m.get("id").and_then(|x| x.as_u64()) {
                    if id != 0 && id >= 900_000 {
                        *low = (*low).min(id);
                    }
                }
                m.items.iter().for_each(|(_, x)| scan(x, low));
            }
            Value::Arr(a) => a.iter().for_each(|x| scan(x, low)),
            _ => {}
        }
    }
    for (k, v) in &pr.doc.items {
        if k != "elements" && k != "library" {
            scan(v, &mut low);
        }
    }
    pr.lib_low = low;
}

/// Puts a family into the project under `name` (over one of that name), as the original leaves
/// it after a command: its library entries made where it has none (the family's, its types' in
/// name order, its parameters' in their order) and taken away for the types and parameters it no
/// longer has; its forms', symbols' and connectors' ids and GUIDs kept where nothing else in the
/// project has them, fresh ones (counting down) where they're missing or taken.
pub fn put_family(pr: &mut Project, name: &str, fam: &Family) {
    remember_lowest(pr);
    let old = family_of(pr, name);
    let file = {
        let p: &Project = pr;
        fam.to_file(&|m: &str| p.lib_guid("material", m))
    };
    crate::structure::types::put_sorted(pr.section_mut("families"), name, file);
    ids::ensure_entry(pr, ids::FAMILY, name);
    for (t, _) in &fam.types {
        ids::ensure_entry(pr, ids::FAMILY_TYPE, &ids::entry_name(name, t));
    }
    for p in &fam.parameters {
        ids::ensure_entry(pr, ids::FAMILY_PARAMETER, &ids::entry_name(name, &p.name));
    }
    if let Some(o) = old {
        for (t, _) in &o.types {
            if fam.type_values(t).is_none() {
                ids::remove_entry(pr, ids::FAMILY_TYPE, &ids::entry_name(name, t));
            }
        }
        for p in &o.parameters {
            if fam.param(&p.name).is_none() {
                ids::remove_entry(pr, ids::FAMILY_PARAMETER, &ids::entry_name(name, &p.name));
            }
        }
    }
    ids::fix_parts(pr, name);
}

/// Puts a family given as a project file holds it (materials by GUID or by name) into the
/// project, as [`put_family`] does: what loading a favorite family needs (its parts get fresh
/// ids, counting down, where the project has theirs, and fresh GUIDs where it has those).
pub fn put_family_value(pr: &mut Project, name: &str, file: &Value) {
    let fam = model::from_file(file, &|s: &str| material_name(pr, s));
    put_family(pr, name, &fam);
}

/// Renames a family: it moves in the file, its library entries follow (keeping their GUIDs).
pub fn rename_family(pr: &mut Project, from: &str, to: &str) {
    let Some(f) = family_of(pr, from) else { return };
    let fams = pr.section_mut("families");
    let v = fams.remove(from).unwrap_or(Value::Null);
    crate::structure::types::put_sorted(fams, to, v);
    ids::rename_entry(pr, ids::FAMILY, from, to);
    for (t, _) in &f.types {
        ids::rename_entry(pr, ids::FAMILY_TYPE, &ids::entry_name(from, t), &ids::entry_name(to, t));
    }
    for p in &f.parameters {
        ids::rename_entry(pr, ids::FAMILY_PARAMETER, &ids::entry_name(from, &p.name), &ids::entry_name(to, &p.name));
    }
}

/// Takes a family away with its library entries.
pub fn remove_family(pr: &mut Project, name: &str) {
    remember_lowest(pr);
    let Some(f) = family_of(pr, name) else { return };
    pr.section_mut("families").remove(name);
    ids::remove_entry(pr, ids::FAMILY, name);
    for (t, _) in &f.types {
        ids::remove_entry(pr, ids::FAMILY_TYPE, &ids::entry_name(name, t));
    }
    for p in &f.parameters {
        ids::remove_entry(pr, ids::FAMILY_PARAMETER, &ids::entry_name(name, &p.name));
    }
}

/// The model rules of this part, checked after every command (and by the original on opening a
/// file): every family, in name order, held to its rules; the first refusal.
pub fn check(pr: &Project) -> R<()> {
    let Some(fams) = pr.section("families") else { return Ok(()) };
    let mut names: Vec<&String> = fams.keys().collect();
    names.sort();
    for n in names {
        let f = model::from_file(fams.get(n).unwrap(), &|s: &str| material_name(pr, s));
        check::rules(&f, &|_m: &str| true).map_err(|e| format!("family `{}`: {}", n, e))?;
    }
    Ok(())
}

/// The components of each family, by family name (for the warnings).
fn placed(pr: &Project) -> Vec<(String, usize)> {
    let mut out: Vec<(String, usize)> = Vec::new();
    for e in pr.elements.values() {
        if e.get("category").and_then(|c| c.as_str()) != Some("component") {
            continue;
        }
        let Some(g) = e.get("family").and_then(|f| f.as_str()) else { continue };
        let Some(n) = name_of_guid(pr, g) else { continue };
        match out.iter_mut().find(|(m, _)| *m == n) {
            Some((_, c)) => *c += 1,
            None => out.push((n, 1)),
        }
    }
    out.sort();
    out
}

/// What `inspect` warns of: each lighting, outlet or switch family in use that has forms and
/// holds no connector, so its devices count as zero load.
pub fn warnings(pr: &Project) -> Vec<String> {
    let mut out = Vec::new();
    for (n, count) in placed(pr) {
        let Some(f) = family_of(pr, &n) else { continue };
        if !matches!(f.category.as_str(), "lighting" | "outlet" | "switch") || !f.connectors.is_empty() || f.forms.is_empty() {
            continue;
        }
        let (what, counts) = if count == 1 { ("device counts", "") } else { ("devices count", "") };
        let _ = counts;
        out.push(format!(
            "family `{}` has no connector, so its {} placed {} as a load of zero: give it one with `family` `connectors`",
            n, count, what
        ));
    }
    out
}

/// The project's families as `inspect` shows them: {name: {category, connectors: [{kind,
/// system}], parameters: [names], types: [names]}}.
pub fn inspect_view(pr: &Project) -> Value {
    let mut out = Map::new();
    let Some(fams) = pr.section("families") else { return Value::Obj(out) };
    for (n, _) in fams.iter() {
        let Some(f) = family_of(pr, n) else { continue };
        let conns: Vec<Value> =
            f.connectors.iter().map(|c| crate::jobj! {"kind" => c.kind.name(), "system" => c.system.name()}).collect();
        out.insert_sorted(
            n,
            crate::jobj! {
                "category" => f.category.as_str(),
                "connectors" => Value::Arr(conns),
                "parameters" => Value::Arr(f.parameters.iter().map(|p| Value::s(&p.name)).collect()),
                "types" => Value::Arr(f.type_names().into_iter().map(Value::Str).collect()),
            },
        );
    }
    Value::Obj(out)
}

/// A family's type worked out, its parameters' values in their order (a hosted family's `Wall
/// Thickness` last): `instance` are a component's (or an opening's) own values by parameter name
/// over the type's, `wall` a hosted family's wall thickness (200 when none). None when the project
/// has no such family or type.
pub fn type_values(
    pr: &Project,
    family: &str,
    ty: &str,
    instance: Option<&Map>,
    wall: Option<f64>,
) -> Option<Result<Vec<(String, PVal)>, String>> {
    let f = family_of(pr, family)?;
    f.type_values(ty)?;
    let ev = Eval::new(&f, Some(ty), instance, wall);
    Some(ev.values())
}

/// A door's or window's family type's opening: (width, height, the sill a window takes by
/// default: its `Sill Height`, 0 when it has none).
pub fn opening_size(pr: &Project, family: &str, ty: &str, instance: Option<&Map>) -> Option<(f64, f64, f64)> {
    let vals = type_values(pr, family, ty, instance, None)?.ok()?;
    let get = |n: &str| vals.iter().find(|(k, _)| k == n).map(|(_, v)| v.num());
    Some((get("Width").unwrap_or(0.0), get("Height").unwrap_or(0.0), get("Sill Height").unwrap_or(0.0)))
}

/// A family's forms worked out for a type (and an instance's values), in its own axes, the voids
/// cut out of the solid forms listed before them: each solid with its material's name.
pub fn pieces_of(pr: &Project, family: &str, ty: &str, instance: Option<&Map>, wall: Option<f64>) -> Vec<Piece> {
    let Some(f) = family_of(pr, family) else { return Vec::new() };
    let ev = Eval::new(&f, Some(ty), instance, wall);
    check::cut(&check::pieces(&f, &ev))
}

/// A family's connectors worked out for a type (and an instance's values).
pub fn connectors_of(pr: &Project, family: &str, ty: &str, instance: Option<&Map>) -> Vec<(model::Connector, ConnectorValues)> {
    let Some(f) = family_of(pr, family) else { return Vec::new() };
    let ev = Eval::new(&f, Some(ty), instance, None);
    f.connectors
        .iter()
        .filter_map(|c| check::connector_values(c, &ev).ok().map(|v| (c.clone(), v)))
        .collect()
}

