def err(keys):
    body = {"family": '"Table"', "at": "[0,0]"}
    for k in keys:
        body[k] = BAD[k]
    s = "{" + ",".join('"%s":%s' % (k, v) for k, v in body.items()) + "}"
    code, out, e = run(['component ' + s])
    return e


single = {k: err([k]) for k in BAD}
for a, b in itertools.combinations(BAD, 2):
