#!/usr/bin/env python3
"""Regression suite: runs each case on the original and mine (as cmp.py does: fresh dirs, outputs
and written files normalised) and reports the failures.
usage: suite.py [cases.py ...] [-k substring] [-v]"""
import os, re, subprocess, sys, tempfile, shutil, difflib, json, importlib.util
from concurrent.futures import ThreadPoolExecutor

ORIG = '/workspace/executable'
MINE = '/workspace/.claude/worktrees/agent-a31569566c799be2a/target/release/bimcraft-cli'
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')


def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}

    def rep(mo):
        g = mo.group(0)
        if g not in m:
            m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    s = GUID.sub(rep, s)
    s = re.sub(r"\.tmp[A-Za-z0-9]{6}", ".tmpXXXXXX", s)
    return s


def run(exe, args, files, env):
    d = tempfile.mkdtemp(prefix='suite', dir='/tmp/family-agent')
    for f in files:
        shutil.copy(f, d)
    e = dict(os.environ)
    e.update(env or {})
    for k, v in list(e.items()):
        e[k] = v.replace('$DIR', d)
    p = subprocess.run([exe] + args, cwd=d, capture_output=True, timeout=300, env=e)
    out = {'stdout': p.stdout.decode('utf-8', 'replace'), 'stderr': p.stderr.decode('utf-8', 'replace'), 'code': str(p.returncode)}
    fl = {}
    for root, dirs, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, d)
            if os.path.basename(f) in [os.path.basename(x) for x in files]:
                continue
            try:
                fl[rel] = open(full, 'rb').read()
            except Exception:
                fl[rel] = b'<unreadable>'
    shutil.rmtree(d)
    return out, fl


def compare(case):
    name, args, files, env = case
    o, of = run(ORIG, args, files, env)
    m, mf = run(MINE, args, files, env)
    diffs = []
    for k in ('code', 'stdout', 'stderr'):
        x, y = norm(o[k]), norm(m[k])
        if x != y:
            d = list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=0))[:12]
            diffs.append('  %s differs:\n    ' % k + '\n    '.join(l[:400] for l in d))
    for f in sorted(set(of) | set(mf)):
        if f not in of:
            diffs.append('  file %s only in mine' % f)
            continue
        if f not in mf:
            diffs.append('  file %s only in orig' % f)
            continue
        try:
            xs, ys = norm(of[f].decode()), norm(mf[f].decode())
        except UnicodeDecodeError:
            if of[f] != mf[f]:
                diffs.append('  binary %s differs' % f)
            continue
        if xs != ys:
            d = list(difflib.unified_diff(xs.splitlines(), ys.splitlines(), 'orig', 'mine', lineterm='', n=1))[:24]
            diffs.append('  file %s differs:\n    ' % f + '\n    '.join(l[:300] for l in d))
    return name, diffs


def load_cases(paths):
    cases = []
    for p in paths:
        spec = importlib.util.spec_from_file_location('cases_%d' % len(cases), p)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        for c in mod.CASES:
            name, cmds = c[0], c[1]
            opts = c[2] if len(c) > 2 else {}
            args = ['run']
            if opts.get('project'):
                args.append(opts['project'])
            for cmd in cmds:
                if isinstance(cmd, tuple):
                    cmd = cmd[0] + ' ' + json.dumps(cmd[1])
                args += ['--cmd', cmd]
            if opts.get('save', True):
                args += ['--save', 'out.bimcraft']
            cases.append((os.path.basename(p) + ':' + name, args, opts.get('files', []), opts.get('env')))
    return cases


def main():
    a = sys.argv[1:]
    verbose = '-v' in a
    a = [x for x in a if x != '-v']
    filt = None
    if '-k' in a:
        i = a.index('-k')
        filt = a[i + 1]
        a = a[:i] + a[i + 2:]
    paths = a or sorted(os.path.join('/tmp/family-agent/cases', f) for f in os.listdir('/tmp/family-agent/cases') if f.endswith('.py'))
    cases = load_cases(paths)
    if filt:
        cases = [c for c in cases if filt in c[0]]
    with ThreadPoolExecutor(max_workers=8) as ex:
        results = list(ex.map(compare, cases))
    fails = [(n, d) for n, d in results if d]
    for n, d in fails:
        print('FAIL', n)
        if verbose or len(fails) <= 30:
            print('\n'.join(d))
    print('%d/%d passed' % (len(results) - len(fails), len(results)))


if __name__ == '__main__':
    main()

