45	/// What a command asks of a family's definition, read in the original's order.
46	#[derive(Default)]
47	struct Change {
48	    category: Option<String>,
49	    parameters: Option<Vec<Param>>,
50	    forms: Option<Vec<Form>>,
51	    symbols: Option<Vec<Symbol>>,
52	    form: Option<Map>,
53	    symbol: Option<Map>,
