121	/// A part chosen by `id` (a number, or one in a string) or `guid`.
122	enum Pick {
123	    Id(u64),
124	    Guid(String),
125	}
126	
127	impl Pick {
128	    fn shown(&self) -> String {
129	        match self {
130	            Pick::Id(n) => n.to_string(),
131	            Pick::Guid(g) => g.clone(),
132	        }
133	    }
134	}
