136	fn pick_of(v: &Value) -> Option<Pick> {
137	    match v {
138	        Value::Num(n) => {
139	            let x = n.as_f64();
140	            if x >= 0.0 && x.fract() == 0.0 {
141	                Some(Pick::Id(x as u64))
142	            } else {
143	                None
144	            }
145	        }
146	        Value::Str(s) => {
147	            let t = s.trim();
148	            if !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit()) {
149	                return t.parse::<u64>().ok().map(Pick::Id);
150	            }
151	            de::real_guid(s).map(Pick::Guid)
152	        }
153	        _ => None,
154	    }
155	}
