164	/// Binds new parts to the old ones by place: one given without an id or a GUID takes those of
165	/// the part in its place before.
166	fn keep_by_place<T>(new: &mut [T], old: &[T], get: impl Fn(&T) -> (Option<u64>, Option<GRef>), set: impl Fn(&mut T, Option<u64>, Option<GRef>)) {
