"""Random families (mostly valid, some broken in one or more ways), created, read, placed and
looked at; compared whole."""
import json, random

R = random.Random(int(__import__('os').environ.get('FUZZ_SEED', '1')))
N = int(__import__('os').environ.get('FUZZ_N', '150'))

KINDS = ['length', 'number', 'angle', 'yesno', 'material']
MATS = ['Timber', 'Concrete', 'Glass', 'Metal', 'Bogus']
CATS = ['furniture', 'casework', 'plumbing', 'lighting', 'generic', 'outlet', 'switch', 'door', 'window', 'drain', 'pipefitting']


def num(lo=-500, hi=2000):
    x = R.choice([R.randint(lo, hi), round(R.uniform(lo, hi), 2), 0, 100, 50])
    return x


def expr(names, depth=0):
    r = R.random()
    if r < 0.45 or depth > 2:
        return num()
    if r < 0.8 and names:
        n = R.choice(names)
        return R.choice(['%s' % n, '%s / 2' % n, '%s + %d' % (n, R.randint(1, 200)), '-%s' % n, '(%s) * 0.5' % n, 'if(%s > 100, %s, 50)' % (n, n)])
    return R.choice(['Q', '1/0', '1 +', 'max(1, 2)', 'sqrt(4) * 25', 'round(12.5)', 'min()', '0/0', 'foo(1)'])


def rect(names, w=None):
    a = expr(names)
    b = expr(names)
    return [[0, 0], [a, 0], [a, b], [0, b]] if R.random() < 0.7 else [[-50, -50], [w or 100, -50], [w or 100, 100]]


def form(names):
    r = R.random()
    f = {}
    if r < 0.6:
        f['profile'] = rect(names)
    elif r < 0.8:
        f['circle'] = {"centre": [expr(names), expr(names)], "radius": R.choice([expr(names), 50, -5, 0.5])}
    elif r < 0.9:
        f['profile'] = [[10, 0], [60, 0], [60, 40]]
        f['axis'] = [[0, 0], [0, R.choice([10, 0])]]
    else:
        f['mesh'] = [[[0, 0, 0], [100, 0, R.choice([0, 50])], [0, 100, R.choice([30, 77])]]]
    if R.random() < 0.3:
        f['plane'] = R.choice(['xy', 'xz', 'yz', 'zz'])
    if R.random() < 0.5:
        f['from'] = R.choice([0, expr(names), 10])
    f['to'] = R.choice([100, expr(names), 360, 0, 90])
    if R.random() < 0.2:
        f['void'] = True
    if R.random() < 0.3:
        f['material'] = R.choice(MATS + ['M'])
    if R.random() < 0.15:
        f['visible'] = R.choice(['Y', '0', 1, 'Q', 'Y = 0'])
    return f


def symbol(names):
    r = R.random()
    s = {}
    if r < 0.4:
        s['line'] = [[0, 0], [expr(names), expr(names)]]
    elif r < 0.6:
        s['arc'] = {"centre": [0, 0], "radius": R.choice([expr(names), 0, 10]), "from": R.choice([0, 90]), "to": R.choice([90, 360, 400])}
    elif r < 0.8:
        s['text'] = {"at": [0, 0], "height": R.choice([10, 0, expr(names)]), "value": R.choice(['A', '{%s}' % (names[0] if names else 'Q'), '', '{Q}', '{A', 'x' * 300])}
    elif r < 0.95:
        s['dot'] = {"centre": [0, 0], "radius": R.choice([5, 0, -1])}
    if R.random() < 0.1:
        s['visible'] = R.choice(['Y', 0])
    return s


def connector(names):
    k = R.choice(['power', 'switch'])
    c = {"kind": k, "system": R.choice(['power-balanced', 'power-unbalanced', 'switch']) if R.random() < 0.3 else ('switch' if k == 'switch' else 'power-balanced')}
    if k == 'power':
        c['voltage'] = R.choice([220, 127, 0, expr(names)])
        if R.random() < 0.5:
            c['load_va'] = R.choice([100, expr(names), -5])
        if R.random() < 0.3:
            c['poles'] = R.choice([1, 2, 3, 4])
        if R.random() < 0.3:
            c['power_factor'] = R.choice([0.9, 1.2, expr(names)])
        if R.random() < 0.3:
            c['classification'] = R.choice(['lighting', 'receptacle', ''])
    return c


def family(i):
    names = []
    params = []
    for j in range(R.randint(0, 5)):
        n = R.choice(['W', 'D', 'H', 'Len', 'Load', 'Y', 'M', 'Thick %d' % j, 'P%d' % j])
        k = R.choice(KINDS) if n not in ('Y', 'M') else ('yesno' if n == 'Y' else 'material')
        p = {"name": n, "kind": k}
        if k == 'material':
            p['value'] = R.choice(MATS[:3] + [None])
        elif k == 'yesno':
            p['value'] = R.choice([True, False, 1, None])
        else:
            p['value'] = num(0, 1500)
        if R.random() < 0.2 and k != 'material' and names:
            p['formula'] = expr(names) if isinstance(expr(names), str) else '%s * 2' % R.choice(names)
        if R.random() < 0.2:
            p['instance'] = True
        params.append(p)
        if k != 'material':
            names.append(n)
    cat = R.choice(CATS)
    body = {"name": "F%d" % i, "category": cat, "parameters": params}
    types = {}
    for t in range(R.randint(1, 3)):
        tv = {}
        for p in params:
            if R.random() < 0.3 and not p.get('instance') and 'formula' not in p:
                tv[p['name']] = R.choice([num(0, 1500), True]) if p['kind'] != 'material' else R.choice(MATS)
        types['T%d' % t] = tv
    body['types'] = types
    if cat in ('door', 'window') and R.random() < 0.8:
        params[:0] = [{"name": "Width", "value": 900}, {"name": "Height", "value": 2100}]
        names[:0] = ['Width', 'Height']
    body['forms'] = [form(names) for _ in range(R.randint(0, 4))]
    if R.random() < 0.5:
        body['symbols'] = [symbol(names) for _ in range(R.randint(1, 3))]
    if R.random() < 0.3:
        body['connectors'] = [connector(names) for _ in range(R.randint(1, 2))]
    if R.random() < 0.1:
        body['kind'] = R.choice(['wc', 'tee', 'floor_drain', 'bogus'])
    if R.random() < 0.1:
        body['operation'] = R.choice(['swing', 'sliding', 'bogus'])
    return body


CASES = []
for i in range(N):
    b = family(i)
    cmds = [('family', b), ('family', {"name": b['name']})]
    if b['category'] not in ('door', 'window'):
        cmds.append(('component', {"family": b['name'], "at": [0, 0], "angle": 30}))
        cmds.append('elements {"category":"component"}')
    cmds.append(('family', {"name": b['name'], "dry_run": True, "types": {"T9": {}}, "forms": b.get('forms', [])[:1]}))
    CASES.append(('fuzz %d' % i, cmds))

