"""Random changes to the project's own families (patches, deletions, replaced lists, merged
types, renames, dry runs), with components placed before and looked at after."""
import json, random, os

R = random.Random(int(os.environ.get('FUZZ_SEED', '1')) + 1000)
N = int(os.environ.get('FUZZ_N', '150'))

FAMS = {
    'Table': {'forms': [999486, 999485, 999484, 999483, 999482], 'params': ['Width', 'Depth', 'Height', 'Thickness', 'Leg Width', 'Material'], 'types': ['1200 x 800', '1600 x 900', '2000 x 1000']},
    'Chair': {'forms': [999595, 999594, 999593, 999592, 999591, 999590], 'params': ['Width', 'Depth', 'Seat Height', 'Height', 'Thickness', 'Leg Width', 'Material'], 'types': ['450 x 450']},
    'Single Door': {'forms': [999525, 999524, 999523, 999522, 999521, 999520], 'symbols': [999519, 999518], 'params': ['Width', 'Height', 'Frame Width', 'Leaf Thickness', 'Frame Material', 'Leaf Material'], 'types': ['1000 x 2100', '800 x 2100', '900 x 2100']},
    'Outlet': {'forms': [999539, 999538], 'connectors': [999537], 'params': ['Mounting Height', 'Load'], 'types': ['High 2100', 'Low 300', 'Medium 1100']},
    'Kitchen Sink': {'forms': [999548, 999547, 999546, 999545, 999544, 999543, 999542, 999541, 999540], 'params': ['Width', 'Depth', 'Height', 'Material'], 'types': ['1200 x 550', '800 x 500']},
    'Ceiling Luminaire': {'forms': [999598, 999597], 'connectors': [999596], 'params': ['Diameter', 'Mounting Height', 'Load'], 'types': ['300', '400']},
}


def val():
    return R.choice([100, 250.5, 0, -50, 'Width / 2', 'Q', '1/0', 'Height - 10', True, None, 'x'])


def form_patch(f):
    p = {"id": R.choice(f['forms'] + [5])}
    for _ in range(R.randint(1, 3)):
        k = R.choice(['to', 'from', 'material', 'visible', 'void', 'plane', 'profile', 'circle', 'bogus'])
        p[k] = {'to': val(), 'from': val(), 'material': R.choice(['Timber', 'Glass', None, 'Bogus', 'Material']), 'visible': R.choice(['1', None, 0, 'Q']),
                'void': R.choice([True, False, None]), 'plane': R.choice(['xz', 'yz', None]), 'profile': R.choice([None, [[0, 0], [100, 0], [100, 100]]]),
                'circle': R.choice([None, {"centre": [0, 0], "radius": 50}]), 'bogus': 1}[k]
    return p


def change(name, f):
    b = {"name": name}
    r = R.random()
    if r < 0.25:
        b['form'] = form_patch(f)
    elif r < 0.35:
        b['delete_form'] = R.sample(f['forms'], min(len(f['forms']), R.randint(1, 2)))
    elif r < 0.45:
        b['types'] = {R.choice(f['types'] + ['New']): R.choice([None, {}, {R.choice(f['params']): val()}])}
    elif r < 0.55:
        ps = [{"name": p, "value": R.choice([100, 200])} for p in f['params'] if R.random() < 0.8]
        b['parameters'] = ps
    elif r < 0.62:
        b['rename'] = R.choice(['Renamed', 'Desk', '  ', name])
    elif r < 0.7:
        b['forms'] = [{"profile": [[0, 0], [100, 0], [100, 100]], "to": R.choice([100, 'Q', 0])} for _ in range(R.randint(0, 3))]
    elif r < 0.78 and 'symbols' in f:
        b['symbol'] = {"id": R.choice(f['symbols']), R.choice(['visible', 'line', 'arc']): R.choice([None, '1', [[0, 0], [1, 1]]])}
    elif r < 0.85 and 'connectors' in f:
        b['connectors'] = [{"kind": "power", "system": "power-balanced", "voltage": R.choice([220, 0, 'Load']), "load_va": R.choice(['Load', 50, -1])}]
    elif r < 0.9:
        b['category'] = R.choice(['casework', 'door', 'lighting', 'generic'])
