249	/// Rotates `p` about the line through `o` along unit `u` by `t` radians (right-handed).
250	fn rotate(p: V3, o: V3, u: V3, t: f64) -> V3 {
251	    // the point's foot on the axis stays; the rest of it turns about it
252	    let foot = add(o, scale(u, dot(sub(p, o), u)));
253	    let r = sub(p, foot);
254	    let (c, sn) = (t.cos(), t.sin());
255	    add(foot, add(scale(r, c), scale(cross(u, r), sn)))
