264	pub fn revolve(plane: super::model::Plane, profile: &[[f64; 2]], axis: [[f64; 2]; 2], from: f64, to: f64) -> Solid {
265	    let p = clean(profile);
266	    let mut s = Solid::default();
267	    if p.len() < 3 {
268	        return s;
269	    }
270	    let o = place(plane, axis[0][0], axis[0][1], 0.0);
271	    let e = sub(place(plane, axis[1][0], axis[1][1], 0.0), o);
272	    let l = len(e);
273	    if l == 0.0 {
274	        return s;
275	    }
276	    let u = scale(e, 1.0 / l);
277	    let span = to - from;
278	    let full = span >= 360.0;
279	    let n_steps = steps(span);
280	    let pts3: Vec<V3> = p.iter().map(|q| place(plane, q[0], q[1], 0.0)).collect();
281	    let ring = |k: usize| -> Vec<V3> {
282	        let t = (from + span * k as f64 / n_steps as f64).to_radians();
283	        pts3.iter().map(|q| rotate(*q, o, u, t)).collect()
284	    };
285	    let rings: Vec<Vec<V3>> = (0..=n_steps).map(ring).collect();
286	    let n = p.len();
287	    let same = |a: V3, b: V3| len(sub(a, b)) < 1e-9;
288	    for k in 0..n_steps {
289	        let (r0, r1) = (&rings[k], if full && k + 1 == n_steps { &rings[0] } else { &rings[k + 1] });
290	        for i in 0..n {
291	            let j = (i + 1) % n;
292	            let mut quad = vec![r0[i], r0[j], r1[j], r1[i]];
293	            quad.dedup_by(|a, b| same(*a, *b));
294	            if quad.len() > 1 && same(quad[0], quad[quad.len() - 1]) {
295	                quad.pop();
296	            }
297	            if quad.len() >= 3 {
298	                s.polys.push(quad);
299	            }
300	        }
301	    }
302	    if !full {
303	        let tris = triangulate(&p);
304	        for t in &tris {
305	            // the start's cap runs against the sides' first edges, the end's with their last
306	            s.polys.push(vec![rings[0][t[2]], rings[0][t[1]], rings[0][t[0]]]);
307	            s.polys.push(vec![rings[n_steps][t[0]], rings[n_steps][t[1]], rings[n_steps][t[2]]]);
308	        }
309	    }
310	    if s.volume() < 0.0 {
311	        s.flip();
312	    }
313	    s
314	}
