11	fn sub(a: V3, b: V3) -> V3 {
12	    [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
13	}
14	fn add(a: V3, b: V3) -> V3 {
15	    [a[0] + b[0], a[1] + b[1], a[2] + b[2]]
16	}
17	fn scale(a: V3, s: f64) -> V3 {
18	    [a[0] * s, a[1] * s, a[2] * s]
19	}
20	fn dot(a: V3, b: V3) -> f64 {
21	    a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
22	}
23	fn cross(a: V3, b: V3) -> V3 {
24	    [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]
25	}
26	fn len(a: V3) -> f64 {
27	    dot(a, a).sqrt()
28	}
29	fn lerp(a: V3, b: V3, t: f64) -> V3 {
30	    add(a, scale(sub(b, a), t))
31	}
