33	/// A box: its least and greatest corners.
34	#[derive(Clone, Copy, Debug, PartialEq)]
35	pub struct Bbox {
36	    pub min: V3,
37	    pub max: V3,
38	}
39	
40	impl Bbox {
41	    pub fn of(points: impl IntoIterator<Item = V3>) -> Option<Bbox> {
42	        let mut b: Option<Bbox> = None;
43	        for p in points {
44	            b = Some(match b {
45	                None => Bbox { min: p, max: p },
46	                Some(mut x) => {
47	                    for i in 0..3 {
48	                        x.min[i] = x.min[i].min(p[i]);
49	                        x.max[i] = x.max[i].max(p[i]);
50	                    }
51	                    x
52	                }
53	            });
54	        }
55	        b
56	    }
57	    /// Whether two boxes share some volume (touching doesn't count).
58	    pub fn overlaps(&self, o: &Bbox) -> bool {
59	        (0..3).all(|i| self.min[i] < o.max[i] && o.min[i] < self.max[i])
60	    }
61	}
