63	/// A closed surface: convex polygons, each turned out (counter-clockwise seen from outside).
64	#[derive(Clone, Debug, Default)]
65	pub struct Solid {
66	    pub polys: Vec<Vec<V3>>,
67	}
68	
69	impl Solid {
70	    pub fn bbox(&self) -> Option<Bbox> {
71	        Bbox::of(self.polys.iter().flat_map(|p| p.iter().copied()))
72	    }
73	    /// Its surface as triangles, turned out.
74	    pub fn triangles(&self) -> Vec<[V3; 3]> {
75	        let mut out = Vec::new();
76	        for p in &self.polys {
77	            for i in 1..p.len().saturating_sub(1) {
78	                out.push([p[0], p[i], p[i + 1]]);
79	            }
80	        }
81	        out
82	    }
83	    /// Its volume (negative where its polygons are turned in).
84	    pub fn volume(&self) -> f64 {
85	        self.triangles().iter().map(|t| dot(t[0], cross(t[1], t[2])) / 6.0).sum()
86	    }
87	    fn flip(&mut self) {
88	        for p in &mut self.polys {
89	            p.reverse();
90	        }
91	    }
92	    /// Moved by a map of points (one that mirrors turns the polygons back out).
93	    pub fn mapped(&self, f: &dyn Fn(V3) -> V3, mirrors: bool) -> Solid {
94	        let mut s = Solid { polys: self.polys.iter().map(|p| p.iter().map(|v| f(*v)).collect()).collect() };
95	        if mirrors {
96	            s.flip();
97	        }
98	        s
99	    }
100	}
