103	pub fn area(p: &[[f64; 2]]) -> f64 {
104	    let n = p.len();
105	    let mut a = 0.0;
106	    for i in 0..n {
107	        let j = (i + 1) % n;
108	        a += p[i][0] * p[j][1] - p[j][0] * p[i][1];
109	    }
110	    a / 2.0
