"""Compares the original's IFC triangles of components with what my local_pieces gives.

Each case: (title, family dict (name Q), [component dicts]). For every case the original runs
`family`, the `component`s, and saves x.ifc and x.bimcraft; my test harness reads x.bimcraft and
dumps local_pieces; the triangles (points and order) must be the same, piece by piece.
"""
import sys, os, re, json, subprocess, tempfile, shutil, glob

ORIG = '/workspace/executable'
TEST = sorted(glob.glob('/workspace/.claude/worktrees/agent-a31569566c799be2a/target/release/deps/bimcraft_cli-*'), key=os.path.getmtime)
TEST = [t for t in TEST if os.access(t, os.X_OK) and not t.endswith('.d')][-1]


def ifc_sets(text):
    out = []
    for m in re.finditer(r"IFCCARTESIANPOINTLIST3D\((\(.*?\))\);\n#\d+=IFCTRIANGULATEDFACESET\(#\d+,\$,\.T\.,(\(.*?\)),\$\);", text):
        pts = re.findall(r"\(([-\d.eE+]+),([-\d.eE+]+),([-\d.eE+]+)\)", m.group(1))
        pts = [tuple(float(c) for c in p) for p in pts]
        tris = [tuple(int(i) for i in t) for t in re.findall(r"\((\d+),(\d+),(\d+)\)", m.group(2))]
        out.append([[pts[i - 1] for i in t] for t in tris])
    return out


def run_case(fam, comps):
    d = tempfile.mkdtemp(prefix='ifcc', dir='/tmp/family-agent')
    args = [ORIG, 'run', '--cmd', 'family ' + json.dumps(fam)]
    for c in comps:
        args += ['--cmd', 'component ' + json.dumps(c)]
    args += ['--save', 'x.ifc', '--save', 'x.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True)
    if p.returncode != 0 or not os.path.exists(os.path.join(d, 'x.ifc')):
        shutil.rmtree(d)
        return None, None, p.stderr.decode()[:300]
    orig = ifc_sets(open(os.path.join(d, 'x.ifc')).read())
    env = dict(os.environ, FAM_IN=os.path.join(d, 'x.bimcraft'), FAM_OUT=os.path.join(d, 'mine.json'))
    q = subprocess.run([TEST, '--ignored', '--exact', 'structure::family::tests::pieces_dump'], cwd=d, capture_output=True, env=env)
    if not os.path.exists(os.path.join(d, 'mine.json')):
        shutil.rmtree(d)
        return orig, None, q.stdout.decode()[-500:] + q.stderr.decode()[-500:]
