"""For one case, labels the original's triangles by index and shows mine as the original's indices.

python3 ifcorder.py CASESFILE TITLE  (env CSGX for my variant)
"""
import sys, os, json
sys.path.insert(0, '/tmp/family-agent')
import importlib.util
from ifccmp import run_case, rnd

spec = importlib.util.spec_from_file_location('c', sys.argv[1])
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
for title, fam, comps in m.CASES:
    if title != sys.argv[2]:
        continue
    orig, mine, err = run_case(fam, comps)
    for k, (a, b) in enumerate(zip(orig, mine)):
        ka = {}
        for i, t in enumerate(a):
            ka.setdefault(rnd(t), i)
        # a triangle of mine: its index in the original's (same corners in the same turn), else '?'
        def key(t):
            r = rnd(t)
            if r in ka:
                return str(ka[r])
            for s in ((r[1], r[2], r[0]), (r[2], r[0], r[1])):
                if s in ka:
                    return '%d~' % ka[s]
            return '?'
        out = [key(t) for t in b]
        print('piece', k, 'orig', len(a), 'mine', len(b))
        print(' '.join(out))

