"""Geometry fuzz: valid families of random solids and voids, placed; their heights compared."""
import json, random, os

R = random.Random(int(os.environ.get('FUZZ_SEED', '1')) + 3000)
N = int(os.environ.get('FUZZ_N', '200'))


def box(x0, y0, x1, y1):
    return [[x0, y0], [x1, y0], [x1, y1], [x0, y1]]


def solid():
    r = R.random()
    if r < 0.4:
        x0, y0 = R.randint(-200, 100), R.randint(-200, 100)
        f = {"profile": box(x0, y0, x0 + R.randint(20, 300), y0 + R.randint(20, 300))}
        a = R.randint(0, 300)
        f.update({"from": a, "to": a + R.randint(10, 500)})
    elif r < 0.6:
        f = {"circle": {"centre": [R.randint(-100, 100), R.randint(-100, 100)], "radius": R.randint(10, 200)}}
        a = R.randint(0, 300)
        f.update({"from": a, "to": a + R.randint(10, 500)})
    elif r < 0.75:
        f = {"plane": R.choice(["xz", "yz"]), "profile": box(R.randint(-100, 0), R.randint(0, 200), R.randint(10, 200), R.randint(220, 600))}
        f.update({"from": -R.randint(10, 100), "to": R.randint(10, 100)})
    elif r < 0.9:
        x = R.randint(10, 100)
        f = {"plane": R.choice(["xz", "xy", "yz"]), "profile": [[x, 0], [x + R.randint(10, 100), 0], [x + 50, R.randint(20, 300)]],
             "axis": [[0, 0], R.choice([[0, 10], [10, 0]])], "from": R.choice([0, -45, 30]), "to": R.choice([90, 180, 360, 270])}
    else:
        # a closed tetrahedron, turned out
        a, b, c = [0, 0, R.randint(0, 100)], [R.randint(50, 200), 0, R.randint(0, 100)], [0, R.randint(50, 200), R.randint(0, 100)]
        d = [R.randint(10, 40), R.randint(10, 40), R.randint(150, 400)]
        tris = [[a, c, b], [a, b, d], [b, c, d], [c, a, d]]
        f = {"mesh": tris}
    return f


CASES = []
fams = []
for i in range(N):
    forms = [solid() for _ in range(R.randint(1, 3))]
    for _ in range(R.randint(1, 3)):
        v = solid()
        v['void'] = True
        forms.insert(R.randint(1, len(forms)), v)
    fams.append({"name": "G%d" % i, "types": {"T": {}}, "forms": forms})
for k in range(0, N, 20):
    cmds = []
    for b in fams[k:k + 20]:
        cmds.append(('family', b))
        cmds.append(('component', {"family": b['name'], "at": [0, 0]}))
    cmds.append('elements {"category":"component"}')
    CASES.append(('geo %d' % k, cmds, {'save': False}))

