"""How close two profile corners must be for the original to keep one: counts triangles in IFC."""
import sys, os, re, json, subprocess, tempfile, shutil
ORIG = '/workspace/executable'


def tris(profile):
    d = tempfile.mkdtemp(prefix='dd', dir='/tmp/family-agent')
    fam = {"name": "Q", "types": {"T": {}}, "forms": [{"profile": profile, "to": 10}]}
    subprocess.run([ORIG, 'run', '--cmd', 'family ' + json.dumps(fam), '--cmd', 'component {"family":"Q","at":[0,0]}', '--save', 'x.ifc'], cwd=d, capture_output=True)
    try:
        text = open(os.path.join(d, 'x.ifc')).read()
    except FileNotFoundError:
        shutil.rmtree(d)
        return 'no ifc'
    shutil.rmtree(d)
    m = re.search(r"IFCTRIANGULATEDFACESET\(#\d+,\$,\.T\.,(\(.*?\)),\$\);", text)
    pts = re.search(r"IFCCARTESIANPOINTLIST3D\((\(.*?\))\);", text)
    return len(re.findall(r"\(\d+,\d+,\d+\)", m.group(1))), len(re.findall(r"\([-\d.E]+,[-\d.E]+,[-\d.E]+\)", pts.group(1)))


for e in sys.argv[1:]:
