"""Compares the original's IFC face sets with mine put through an IFC-like writer: points merged
by their coordinates rounded to 3 decimals (the first one's kept), in order of first use, and
triangles that come to repeat a point left out.  python3 ifcmerge.py CASESFILE [title]"""
import sys, os, importlib.util
sys.path.insert(0, '/tmp/family-agent')
from ifccmp import run_case, close, rnd


def merged(tris):
    keys = {}
    pts = []
    out = []
    for t in tris:
        idx = []
        for v in t:
            k = tuple(round(c * 1000) for c in v)
            if k not in keys:
                keys[k] = len(pts)
                pts.append(v)
            idx.append(keys[k])
        if len(set(idx)) == 3:
            out.append(tuple(idx))
    # the original lists only points that are used
    return pts, out


def faceset(pts, tris):
    used = []
    seen = {}
    res = []
    for t in tris:
        r = []
        for i in t:
            if i not in seen:
                seen[i] = len(used)
                used.append(pts[i])
            r.append(seen[i])
        res.append(tuple(r))
    return used, res


if __name__ == '__main__':
    spec = importlib.util.spec_from_file_location('c', sys.argv[1])
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    only = sys.argv[2] if len(sys.argv) > 2 else None
    ok = n = 0
    for title, fam, comps in m.CASES:
        if only and only != title:
            continue
        orig, mine, err = run_case(fam, comps)
        if orig is None or mine is None:
            print('ERROR', title, err[:200])
            continue
        n += 1
        bad = ''
        if len(orig) != len(mine):
            bad = 'pieces %d %d' % (len(orig), len(mine))
        else:
            for k, (a, b) in enumerate(zip(orig, mine)):
                pa, ta = merged(a)
                pa, ta = faceset(pa, ta)
                pb, tb = merged(b)
                pb, tb = faceset(pb, tb)
                if ta != tb:
                    bad = 'piece %d: triangles differ (%d vs %d)' % (k, len(ta), len(tb))
                    break
                if len(pa) != len(pb) or not all(close(x, y) for x, y in zip(pa, pb)):
                    bad = 'piece %d: points differ' % k
                    break
        if bad:
            print('DIFF', title, bad)
        else:
            ok += 1
    print('ok', ok, 'of', n)

