"""The 20000-triangle limit: B33 (seed 3) with its forms 1, 2 and further voids, and against other
refusals; the original's answer and whether mine is the same."""
import sys, json, subprocess
sys.path.insert(0, '/tmp/family-agent')
from lib import ORIG, MINE
b = json.load(open('/tmp/family-agent/b33.json'))
s, v2, v3 = b['forms']
far = {"profile": [[5000, 0], [5100, 0], [5100, 100], [5000, 100]], "to": 100, "void": True}
bad = {"profile": [[0, 0], [1, 0], [2, 0]], "to": 10}
badf = {"profile": [[0, 0], [100, 0], [100, 100]], "to": "Nope"}
T = {"T": {}}
cases = {
    'orig': ([s, v2, v3], T),
    'far void after': ([s, v2, far], T),
    'far void then v3': ([s, v2, far, v3], T),
    'v3 alone': ([s, v3], T),
    'two solids, far void': ([s, v2, {"profile": [[5000, 0], [5100, 0], [5100, 100], [5000, 100]], "to": 100}, far], T),
    'limit then bad form': ([s, v2, v3, bad], T),
    'limit then bad formula form': ([s, v2, v3, badf], T),
    'bad form before': ([bad, s, v2, v3], T),
}
for name, (forms, types) in cases.items():
    fam = {"name": "H", "types": types, "forms": forms}
    outs = []
    for exe in (ORIG, MINE):
        p = subprocess.run([exe, 'run', '--cmd', 'family ' + json.dumps(fam)], capture_output=True, text=True, cwd='/tmp/family-agent')
        outs.append((p.returncode, p.stdout, p.stderr))
    print(name, '->', 'ok' if outs[0][0] == 0 else outs[0][2].strip()[:200], flush=True)
    print('   SAME' if outs[0] == outs[1] else '   DIFF mine: ' + (outs[1][2].strip()[:300] or outs[1][1][:200]), flush=True)

